```javascript
const fs = require('fs');
const fsPromises = require('fs/promises');

const DEFAULT_CONFIG = {
  port: 3000,
  host: 'localhost',
  debug: false,
  logLevel: 'info',
};

/**
 * Checks whether a value is a plain object (not null, not an array).
 */
function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Recursively merges `source` into `target`, returning a new object.
 * Nested objects are merged; arrays and primitives are replaced.
 */
function deepMerge(target, source) {
  const result = { ...target };
  for (const [key, value] of Object.entries(source)) {
    if (isPlainObject(value) && isPlainObject(result[key])) {
      result[key] = deepMerge(result[key], value);
    } else {
      result[key] = value;
    }
  }
  return result;
}

/**
 * Asynchronously loads a JSON config file.
 * Returns defaults if the file is missing, unreadable, or contains invalid JSON.
 * Valid configs are merged on top of the defaults so missing keys are filled in.
 *
 * @param {string} filePath - Path to the JSON config file.
 * @param {object} [defaults=DEFAULT_CONFIG] - Default configuration values.
 * @returns {Promise<object>} The resolved configuration.
 */
async function loadConfig(filePath, defaults = DEFAULT_CONFIG) {
  try {
    const raw = await fsPromises.readFile(filePath, 'utf8');
    const parsed = JSON.parse(raw);

    if (!isPlainObject(parsed)) {
      console.warn(`Config at "${filePath}" is not a JSON object; using defaults.`);
      return structuredClone(defaults);
    }

    return deepMerge(defaults, parsed);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn(`Config file "${filePath}" not found; using defaults.`);
    } else if (err instanceof SyntaxError) {
      console.warn(`Invalid JSON in "${filePath}": ${err.message}; using defaults.`);
    } else {
      console.warn(`Could not read "${filePath}": ${err.message}; using defaults.`);
    }
    return structuredClone(defaults);
  }
}

/**
 * Synchronous version of loadConfig, useful at application startup.
 */
function loadConfigSync(filePath, defaults = DEFAULT_CONFIG) {
  try {
    const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));

    if (!isPlainObject(parsed)) {
      console.warn(`Config at "${filePath}" is not a JSON object; using defaults.`);
      return structuredClone(defaults);
    }

    return deepMerge(defaults, parsed);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn(`Config file "${filePath}" not found; using defaults.`);
    } else if (err instanceof SyntaxError) {
      console.warn(`Invalid JSON in "${filePath}": ${err.message}; using defaults.`);
    } else {
      console.warn(`Could not read "${filePath}": ${err.message}; using defaults.`);
    }
    return structuredClone(defaults);
  }
}

module.exports = { loadConfig, loadConfigSync, DEFAULT_CONFIG };
```

**Usage:**

