    return structuredClone(defaults);
  }

  return parseConfig(raw, defaults, merge, onError);
}

/**
 * Shared parsing/validation logic.
 */
function parseConfig(raw, defaults, merge, onError) {
  let parsed;
  try {
    // Strip a UTF-8 BOM if present (common with files saved on Windows)
    parsed = JSON.parse(raw.replace(/^\uFEFF/, ''));
  } catch (err) {
    onError(err, 'invalid-json');
    return structuredClone(defaults);
  }

  if (!isPlainObject(parsed)) {
    onError(new TypeError('Config root must be a JSON object'), 'invalid-shape');
    return structuredClone(defaults);
  }

  return merge ? deepMerge(structuredClone(defaults), parsed) : parsed;
}

module.exports = { loadConfig, loadConfigSync };
