## Design notes

- **Missing vs. unreadable vs. invalid**: The `onError` callback receives a `reason` (`'missing'`, `'unreadable'`, `'invalid-json'`, `'invalid-shape'`) so you can log differently. A missing file is often expected, while a malformed one usually deserves a warning.
- **Defaults are cloned** with `structuredClone` (Node 17+), so callers can't accidentally mutate your shared defaults object.
- **Deep merge** means a partial config file only overrides what it specifies. Pass `{ merge: false }` to get the raw file contents instead.
- **Shape check**: Valid JSON like `42` or `[1,2]` isn't a usable config, so it's treated as invalid.
- **BOM stripping** avoids a confusing `JSON.parse` failure on files saved by some Windows editors.

If you're on Node < 17, replace `structuredClone(defaults)` with `JSON.parse(JSON.stringify(defaults))`.

Here's a robust implementation with both async and sync versions:

```javascript
const fs = require('fs');
const fsPromises = require('fs/promises');

/**
 * Reads a JSON config file and merges it with defaults.
 * Returns defaults if the file is missing, unreadable, or contains invalid JSON.
 *
 * @param {string} filePath - Path to the JSON config file
 * @param {object} defaults - Default configuration values
 * @param {object} [options]
 * @param {boolean} [options.merge=true] - Merge file values over defaults (vs. replace)
 * @param {function} [options.onError] - Optional callback for logging errors
 * @returns {Promise<object>} The resulting configuration
 */
async function loadConfig(filePath, defaults = {}, options = {}) {
  const { merge = true, onError } = options;

  try {
    const raw = await fsPromises.readFile(filePath, 'utf8');
    const parsed = JSON.parse(raw);

    // Ensure the parsed value is a plain object (not null, array, string, etc.)
    if (!isPlainObject(parsed)) {
      throw new TypeError('Config file must contain a JSON object');
    }

    return merge ? deepMerge(defaults, parsed) : parsed;
  } catch (err) {
    if (onError) {
      const reason =
        err.code === 'ENOENT' ? 'missing' :
        err instanceof SyntaxError ? 'invalid JSON' :
        'unreadable or invalid';
      onError(err, reason);
    }
    return structuredClone(defaults); // Return a copy so callers can't mutate defaults
  }
}

/**
 * Synchronous version of loadConfig.
 */
function loadConfigSync(filePath, defaults = {}, options = {}) {
  const { merge = true, onError } = options;

  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    const parsed = JSON.parse(raw);

    if (!isPlainObject(parsed)) {
      throw new TypeError('Config file must contain a JSON object');
    }

    return merge ? deepMerge(defaults, parsed) : parsed;
  } catch (err) {
    if (onError) onError(err);
    return structuredClone(defaults);
  }
}

// --- Helpers ---

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Recursively merges `source` into a copy of `target`.
 * Nested objects are merged; arrays and primitives are replaced.
 */
function deepMerge(target, source) {
  const result = structuredClone(target);

  for (const [key, value] of Object.entries(source)) {
    // Guard against prototype pollution
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      continue;
    }

    if (isPlainObject(value) && isPlainObject(result[key])) {
      result[key] = deepMerge(result[key], value);
    } else {
      result[key] = value;
    }
  }

  return result;
}

module.exports = { loadConfig, loadConfigSync };
```

