### Key design choices

| Feature | Why |
|---|---|
| **Deep merge** | A partial config file (e.g., only overriding `port`) still gets all other defaults, including nested ones. |
| **Type check on parsed value** | `JSON.parse` happily accepts `"hello"`, `42`, `null`, or `[]`, all valid JSON but not valid configs. |
| **`structuredClone(defaults)`** | Prevents callers from accidentally mutating your shared defaults object. |
| **Prototype pollution guard** | Skips `__proto__`/`constructor` keys so a malicious config can't tamper with `Object.prototype`. |
| **Optional `onError`** | Silent by default, but lets you log why defaults were used (missing vs. malformed). |

> **Note:** `structuredClone` requires Node.js 17+. For older versions, replace it with `JSON.parse(JSON.stringify(obj))`, which works fine for JSON-compatible defaults.

Here's a robust Node.js implementation that handles missing files, invalid JSON, and partial configs by merging with defaults:

```javascript
const fs = require('fs');
const path = require('path');

/**
 * Reads a JSON config file and merges it with defaults.
 * Falls back to defaults if the file is missing, unreadable, or invalid.
 *
 * @param {string} filePath - Path to the JSON config file
 * @param {object} defaults - Default configuration values
 * @param {object} [options]
 * @param {boolean} [options.silent=false] - Suppress warning logs
 * @returns {object} The resulting configuration
 */
function loadConfig(filePath, defaults = {}, { silent = false } = {}) {
  const warn = (msg) => { if (!silent) console.warn(`[config] ${msg}`); };
  const resolvedPath = path.resolve(filePath);

  let raw;
  try {
    raw = fs.readFileSync(resolvedPath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      warn(`Config file not found at ${resolvedPath}, using defaults.`);
    } else {
      warn(`Could not read config file (${err.code || err.message}), using defaults.`);
    }
    return structuredClone(defaults);
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    warn(`Invalid JSON in ${resolvedPath}: ${err.message}. Using defaults.`);
    return structuredClone(defaults);
  }

  // Config must be a plain object to merge meaningfully
  if (!isPlainObject(parsed)) {
    warn(`Config in ${resolvedPath} is not a JSON object, using defaults.`);
    return structuredClone(defaults);
  }

  return deepMerge(defaults, parsed);
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Deeply merges `override` into `base` without mutating either.
 * Arrays and primitives in `override` replace those in `base`.
 */
function deepMerge(base, override) {
  const result = structuredClone(base);
  for (const [key, value] of Object.entries(override)) {
    // Guard against prototype pollution
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;

    if (isPlainObject(value) && isPlainObject(result[key])) {
      result[key] = deepMerge(result[key], value);
    } else {
      result[key] = value;
    }
  }
  return result;
}

module.exports = { loadConfig };
```

