Here's a Node.js script that copies a directory and handles errors with clear, friendly messages:

```javascript
#!/usr/bin/env node

/**
 * copy-dir.js
 * Usage: node copy-dir.js <source> <destination> [--overwrite]
 */

const fs = require('fs/promises');
const path = require('path');

// Map common error codes to friendly explanations
const FRIENDLY_ERRORS = {
  ENOENT: 'The source folder could not be found. Double-check the path and try again.',
  EACCES: "You don't have permission to access one of these locations. Try a different folder or check its permissions.",
  EPERM: 'The operation was not permitted. A file may be locked or protected by the system.',
  EEXIST: 'The destination already exists. Use --overwrite if you want to replace it.',
  ENOSPC: "There isn't enough disk space to finish copying.",
  ENOTDIR: 'Part of the path you gave is a file, not a folder.',
  EISDIR: 'Expected a file but found a folder instead.',
  EBUSY: 'A file is currently in use by another program. Close it and try again.',
  EMFILE: 'Too many files are open at once. Try closing some programs and run again.',
  ERR_FS_CP_EINVAL: "You can't copy a folder into itself. Choose a destination outside the source folder.",
  ERR_FS_CP_DIR_TO_NON_DIR: 'The destination is a file, not a folder.',
};

function friendlyMessage(err) {
  return FRIENDLY_ERRORS[err.code] || 'Something unexpected went wrong while copying.';
}

function printUsage() {
  console.log('Usage: node copy-dir.js <source> <destination> [--overwrite]');
}

async function copyDirectory(src, dest, overwrite) {
  // Validate the source before starting
  let stats;
  try {
    stats = await fs.stat(src);
  } catch (err) {
    err.friendlyContext = `Couldn't read source "${src}".`;
    throw err;
  }

  if (!stats.isDirectory()) {
    const err = new Error(`"${src}" is not a directory.`);
    err.code = 'ENOTDIR';
    throw err;
  }

  // Prevent copying a folder into itself
  const relative = path.relative(src, dest);
  if (relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative))) {
    const err = new Error('Destination is inside source.');
    err.code = 'ERR_FS_CP_EINVAL';
    throw err;
  }

  // Check destination
  try {
    await fs.access(dest);
    if (!overwrite) {
      const err = new Error(`"${dest}" already exists.`);
      err.code = 'EEXIST';
      throw err;
    }
  } catch (err) {
    if (err.code !== 'ENOENT') throw err; // ENOENT means dest doesn't exist: good
  }

  await fs.cp(src, dest, {
    recursive: true,
    force: overwrite,
    errorOnExist: !overwrite,
  });
}

async function main() {
  const args = process.argv.slice(2);
  const overwrite = args.includes('--overwrite');
  const [source, destination] = args.filter((a) => !a.startsWith('--'));

  if (!source || !destination) {
    console.error('⚠️  Please provide both a source and a destination folder.\n');
    printUsage();
    process.exit(1);
  }

  const src = path.resolve(source);
  const dest = path.resolve(destination);

  console.log(`📁 Copying "${src}" → "${dest}"...`);

  try {
    await copyDirectory(src, dest, overwrite);
    console.log('✅ Done! Your folder was copied successfully.');
  } catch (err) {
    console.error('\n❌ Sorry, the copy didn\'t complete.');
    if (err.friendlyContext) console.error(`   ${err.friendlyContext}`);
    console.error(`   ${friendlyMessage(err)}`);

    // Show technical details only when debugging
    if (process.env.DEBUG) {
      console.error('\n--- Technical details ---');
      console.error(err);
    } else {
      console.error('   (Run with DEBUG=1 for technical details.)');
    }
    process.exit(1);
  }
}

main();
```

