#!/usr/bin/env node

/**
 * copy-dir.js
 * Recursively copies a directory with friendly error messages.
 *
 * Usage: node copy-dir.js <source> <destination> [--overwrite]
 */

const fs = require("fs/promises");
const path = require("path");

// Map common system error codes to human-friendly explanations
const friendlyMessages = {
  ENOENT: "The file or folder doesn't exist. Double-check the path for typos.",
  EACCES: "Permission denied. Try running with elevated privileges or check folder permissions.",
  EPERM: "The operation isn't permitted. The file may be locked or protected.",
  EEXIST: "Something already exists at the destination. Use --overwrite to replace it.",
  ENOSPC: "Your disk is full. Free up some space and try again.",
  ENOTDIR: "Part of the path is a file, not a folder.",
  EISDIR: "Expected a file but found a folder instead.",
  EBUSY: "The file or folder is in use by another program. Close it and try again.",
  EMFILE: "Too many files are open at once. Try closing other programs.",
  ENAMETOOLONG: "A file or folder name is too long for your system.",
  EROFS: "The destination is on a read-only drive.",
};

function explainError(err) {
  const friendly = friendlyMessages[err.code];
  const location = err.path ? `\n   📍 Location: ${err.path}` : "";
  if (friendly) {
    return `${friendly}${location}`;
  }
  return `An unexpected problem occurred: ${err.message}${location}`;
}

async function pathExists(p) {
  try {
    await fs.access(p);
    return true;
  } catch {
    return false;
  }
}

async function copyDirectory(src, dest, overwrite) {
  const stats = { files: 0, folders: 0 };

  async function copyRecursive(currentSrc, currentDest) {
    await fs.mkdir(currentDest, { recursive: true });
    stats.folders++;

    const entries = await fs.readdir(currentSrc, { withFileTypes: true });

    for (const entry of entries) {
      const srcPath = path.join(currentSrc, entry.name);
      const destPath = path.join(currentDest, entry.name);

      if (entry.isDirectory()) {
        await copyRecursive(srcPath, destPath);
      } else if (entry.isSymbolicLink()) {
        const target = await fs.readlink(srcPath);
        if (overwrite && (await pathExists(destPath))) {
          await fs.unlink(destPath);
        }
        await fs.symlink(target, destPath);
        stats.files++;
      } else {
        // COPYFILE_EXCL makes the copy fail if the destination file exists
        const mode = overwrite ? 0 : fs.constants.COPYFILE_EXCL;
        await fs.copyFile(srcPath, destPath, mode);
        stats.files++;
      }
    }
  }

  await copyRecursive(src, dest);
  return stats;
}

async function main() {
  const args = process.argv.slice(2);
  const overwrite = args.includes("--overwrite");
  const [source, destination] = args.filter((a) => !a.startsWith("--"));

  if (!source || !destination) {
    console.log("👋 Hi there! Here's how to use this script:\n");
    console.log("   node copy-dir.js <source> <destination> [--overwrite]\n");
    console.log("Example:");
    console.log("   node copy-dir.js ./photos ./photos-backup");
    process.exit(1);
  }

  const src = path.resolve(source);
  const dest = path.resolve(destination);

  try {
    // Validate source
    const srcStat = await fs.stat(src).catch((err) => {
      if (err.code === "ENOENT") {
        throw Object.assign(new Error(), {
          friendly: `Couldn't find the source folder "${source}". Is the path correct?`,
        });
      }
      throw err;
    });

    if (!srcStat.isDirectory()) {
      throw Object.assign(new Error(), {
        friendly: `"${source}" is a file, not a folder. This script copies folders only.`,
      });
    }

    // Prevent copying a folder into itself (would loop forever)
    const relative = path.relative(src, dest);
    if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative))) {
      throw Object.assign(new Error(), {
        friendly: "You can't copy a folder into itself. Please choose a destination outside the source folder.",
      });
    }

    // Warn about existing destination
    if ((await pathExists(dest)) && !overwrite) {
      throw Object.assign(new Error(), {
        friendly: `The destination "${destination}" already exists.\n   Add --overwrite if you want to merge into it and replace matching files.`,
      });
    }

    console.log(`📂 Copying "${source}" → "${destination}"...`);
    const stats = await copyDirectory(src, dest, overwrite);
    console.log(`✅ All done! Copied ${stats.files} file(s) across ${stats.folders} folder(s).`);
  } catch (err) {
    console.error("\n😕 Oops, something went wrong while copying.\n");
    console.error(`   ${err.friendly || explainError(err)}\n`);

    if (process.env.DEBUG) {
      console.error("Technical details:", err);
    } else {
      console.error("   (Run with DEBUG=1 for technical details.)");
    }
    process.exit(1);
  }
}

main();
