    case "SAME_PATH":
      return "The source and destination are the same. Please choose a different destination.";
    case "INSIDE_SOURCE":
      return "The destination is inside the source directory, which would cause an endless copy. Choose a location outside the source.";
    default:
      return `Something unexpected happened: ${err.message}`;
  }
