  await fs.cp(src, dest, { recursive: true, errorOnExist: true, force: false });
  return { src, dest };
}

async function main() {
  const [, , source, destination] = process.argv;

  if (!source || !destination) {
    console.log("Usage: node copy-dir.js <source> <destination>");
    console.log("Example: node copy-dir.js ./photos ./photos-backup");
    process.exit(1);
  }

  try {
    const { src, dest } = await copyDirectory(source, destination);
    console.log(`✅ All done! Copied "${src}" to "${dest}".`);
  } catch (err) {
    console.error("😕 Oops, the copy didn't work.");
    console.error(`   ${friendlyMessage(err, source, destination)}`);
    if (process.env.DEBUG) {
      console.error("\nTechnical details:\n", err);
