  ENOENT: "We couldn't find that file or folder. Double-check the path and try again.",
  EACCES: "Permission denied. You may need to run this with elevated privileges or check folder permissions.",
  EPERM: "The operation isn't permitted. The file might be locked or protected by the system.",
