 */

const fs = require("fs/promises");
const path = require("path");

// Map common error codes to human-friendly messages
function friendlyMessage(err, src, dest) {
  switch (err.code) {
    case "ENOENT":
      return `Couldn't find "${err.path || src}". Double-check that the path exists and is spelled correctly.`;
    case "EACCES":
    case "EPERM":
      return `Permission denied for "${err.path}". Try running with appropriate permissions or choose a different location.`;
    case "ENOTDIR":
      return `"${err.path || src}" isn't a directory. Please provide a folder to copy.`;
    case "ENOSPC":
      return `There isn't enough disk space to finish copying to "${dest}".`;
    case "EEXIST":
      return `"${err.path || dest}" already exists and couldn't be overwritten.`;
    case "EROFS":
      return `"${dest}" is on a read-only file system.`;
    case "EMFILE":
      return `Too many files are open at once. Try again, or close other programs.`;
    default:
      return `Something unexpected happened: ${err.message}`;
  }
}

async function copyDirectory(src, dest) {
  const stats = await fs.stat(src);
  if (!stats.isDirectory()) {
    const err = new Error("Source is not a directory");
    err.code = "ENOTDIR";
    err.path = src;
    throw err;
  }

  // Prevent copying a folder into itself (would recurse forever)
  const resolvedSrc = path.resolve(src);
  const resolvedDest = path.resolve(dest);
  if (
    resolvedDest === resolvedSrc ||
    resolvedDest.startsWith(resolvedSrc + path.sep)
  ) {
    const err = new Error(
      "Destination is inside the source directory"
    );
    err.code = "ESELF";
    throw err;
  }

  await fs.mkdir(dest, { recursive: true });
  const entries = await fs.readdir(src, { withFileTypes: true });

  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);

    if (entry.isDirectory()) {
      await copyDirectory(srcPath, destPath);
    } else if (entry.isSymbolicLink()) {
      const target = await fs.readlink(srcPath);
      await fs.symlink(target, destPath).catch((e) => {
        if (e.code !== "EEXIST") throw e;
      });
    } else {
      await fs.copyFile(srcPath, destPath);
    }
  }
}

async function main() {
  const [src, dest] = process.argv.slice(2);

  if (!src || !dest) {
    console.log("Usage: node copy-dir.js <source> <destination>");
    process.exit(1);
  }

  try {
    await copyDirectory(src, dest);
    console.log(`✅ Done! Copied "${src}" to "${dest}".`);
  } catch (err) {
    const msg =
      err.code === "ESELF"
        ? "You can't copy a folder into itself. Please pick a destination outside the source folder."
        : friendlyMessage(err, src, dest);
    console.error(`❌ Oops! ${msg}`);
    process.exit(1);
  }
}

main();
