const fs = require('fs');

/**
 * Reads a JSON config file and merges it over the provided defaults.
 * Returns the defaults if the file is missing, unreadable, or invalid.
 *
 * @param {string} filePath - Path to the JSON config file.
 * @param {object} defaults - Default config values.
 * @returns {object} The resulting config.
 */
function loadConfig(filePath, defaults = {}) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code !== 'ENOENT') {
      console.warn(`Could not read config "${filePath}": ${err.message}`);
    }
    return { ...defaults };
  }

  let parsed;
  try {
    // Strip a UTF-8 BOM if present, since JSON.parse rejects it
    parsed = JSON.parse(raw.replace(/^\uFEFF/, ''));
  } catch (err) {
    console.warn(`Invalid JSON in "${filePath}": ${err.message}`);
    return { ...defaults };
  }

  // Must be a plain object (not null, an array, or a primitive)
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    console.warn(`Config "${filePath}" must contain a JSON object.`);
    return { ...defaults };
  }

  return { ...defaults, ...parsed };
}

module.exports = loadConfig;
```

**Usage:**

```javascript
const loadConfig = require('./loadConfig');

const config = loadConfig('./config.json', {
  port: 3000,
  host: 'localhost',
  debug: false,
});

console.log(config.port);
```

**Design notes:**

- **Missing file** (`ENOENT`) silently returns defaults, since that's often a normal situation. Other read errors, like permission problems, log a warning.
- **Invalid JSON** is caught and logged, and defaults are returned.
- **Wrong shape**: valid JSON like `[]`, `null`, or `42` is rejected, since config should be an object.
- **Merging**: values in the file override defaults, and missing keys fall back to defaults. The merge is shallow. If you have nested config objects, you'd want a deep merge.
- **Defaults are copied**, so callers can't accidentally mutate your original defaults object.

**Async version** (if you prefer not to block the event loop):

```javascript
