const fs = require('fs');
const path = require('path');

/**
 * Reads a JSON config file and merges it over a set of defaults.
 * Falls back to defaults if the file is missing, unreadable, or invalid.
 *
 * @param {string} filePath - Path to the JSON config file.
 * @param {object} defaults - Default configuration values.
 * @returns {object} The resulting configuration.
 */
function loadConfig(filePath, defaults = {}) {
  const resolved = path.resolve(filePath);

  let raw;
  try {
    raw = fs.readFileSync(resolved, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn(`Config file not found: ${resolved}. Using defaults.`);
    } else {
      console.warn(`Could not read config file (${err.message}). Using defaults.`);
    }
    return { ...defaults };
  }

  let parsed;
  try {
    // Strip UTF-8 BOM if present, since JSON.parse would choke on it
    parsed = JSON.parse(raw.replace(/^\uFEFF/, ''));
  } catch (err) {
    console.warn(`Invalid JSON in ${resolved}: ${err.message}. Using defaults.`);
    return { ...defaults };
  }

  // Must be a plain object (not null, an array, or a primitive)
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    console.warn(`Config in ${resolved} is not a JSON object. Using defaults.`);
    return { ...defaults };
  }

  return { ...defaults, ...parsed };
}

module.exports = loadConfig;
```

**Usage:**

```javascript
const loadConfig = require('./loadConfig');

const config = loadConfig('./config.json', {
  port: 3000,
  host: 'localhost',
  debug: false,
});

console.log(config.port);
```

**How it works:**
- **Missing file or read error:** returns a copy of the defaults.
- **Invalid JSON:** the `JSON.parse` error is caught and defaults are returned.
- **Valid JSON but wrong shape** (e.g. an array or `null`): also falls back to defaults.
- **Valid config:** values from the file override the defaults. Any keys missing from the file keep their default values.

**Notes:**
- The merge is shallow. If you have nested objects and want them merged too, you'd need a deep merge (e.g. `lodash.merge`) instead of the spread operator.
- It uses synchronous reads, which is fine for startup config. For an async version, swap in `fs.promises.readFile` and make the function `async`.

