Here's a Node.js script that copies a directory recursively and handles errors with friendly messages. It uses only built-in modules (Node 16.7+ for `fs.cp`).

```js
#!/usr/bin/env node
// copy-dir.js
// Usage: node copy-dir.js <source> <destination>

const fs = require('fs/promises');
const path = require('path');

function friendlyMessage(err, src, dest) {
  switch (err.code) {
    case 'ENOENT':
      return `I couldn't find "${err.path || src}". Please check that the path exists and is spelled correctly.`;
    case 'EACCES':
    case 'EPERM':
      return `I don't have permission to access "${err.path || src}". Try changing the permissions or running with the appropriate privileges.`;
    case 'ENOSPC':
      return `There's not enough disk space to finish copying to "${dest}".`;
    case 'ENOTDIR':
      return `Part of the path isn't a directory: "${err.path || src}".`;
    case 'EEXIST':
      return `Something already exists at "${err.path || dest}" and I didn't want to overwrite it.`;
    case 'EMFILE':
      return `Too many files are open at once. Try closing some programs and run it again.`;
    case 'ERR_FS_CP_EINVAL':
    case 'ERR_FS_CP_DIR_TO_NON_DIR':
    case 'ERR_FS_CP_NON_DIR_TO_DIR':
      return `The source and destination aren't compatible (${err.message}).`;
    default:
      return `Something unexpected happened: ${err.message}`;
  }
}

async function copyDirectory(src, dest) {
  const srcPath = path.resolve(src);
  const destPath = path.resolve(dest);

  // Validate source
  const stats = await fs.stat(srcPath);
  if (!stats.isDirectory()) {
    throw Object.assign(new Error('Source is not a directory'), {
      code: 'ENOTDIR',
      path: srcPath,
    });
  }

  // Prevent copying a folder into itself
  const relative = path.relative(srcPath, destPath);
  if (relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative))) {
    throw new Error('The destination cannot be the same as, or inside, the source folder.');
  }

  await fs.cp(srcPath, destPath, {
    recursive: true,
    errorOnExist: false,
    force: true,
  });

  return { srcPath, destPath };
}

async function main() {
  const [src, dest] = process.argv.slice(2);

  if (!src || !dest) {
    console.log('👋 Usage: node copy-dir.js <source> <destination>');
    process.exit(1);
  }

  try {
    const { srcPath, destPath } = await copyDirectory(src, dest);
    console.log(`✅ All done! Copied "${srcPath}" to "${destPath}".`);
  } catch (err) {
    console.error(`😕 Oops! ${friendlyMessage(err, src, dest)}`);
    process.exit(1);
  }
}

main();
```

**Usage**

```bash
node copy-dir.js ./my-folder ./my-folder-backup
```

**How it works**

- **`fs.cp` with `recursive: true`** copies the whole tree, including subdirectories.
- **Validation** confirms the source exists and is a directory, and prevents copying a folder into itself (which would otherwise recurse badly).
- **`friendlyMessage`** translates common error codes (missing path, permissions, full disk, etc.) into plain language, with a fallback for anything unexpected.
- **Exit codes**: it exits with `1` on failure so it works well in shell scripts.

