Here's a Node.js script that copies a directory recursively and handles errors with friendly messages. It uses `fs.cp` (Node 16.7+).

```js
#!/usr/bin/env node
// copy-dir.js
// Usage: node copy-dir.js <source> <destination>

const fs = require('fs/promises');
const path = require('path');

async function copyDirectory(src, dest) {
  const srcPath = path.resolve(src);
  const destPath = path.resolve(dest);

  // Check that the source exists and is a directory
  const stats = await fs.stat(srcPath);
  if (!stats.isDirectory()) {
    const err = new Error('Source is not a directory');
    err.code = 'ENOTDIR';
    throw err;
  }

  // Prevent copying a directory into itself
  const relative = path.relative(srcPath, destPath);
  if (relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative))) {
    const err = new Error('Destination is inside the source');
    err.code = 'EINSIDE';
    throw err;
  }

  await fs.cp(srcPath, destPath, { recursive: true });
  return { srcPath, destPath };
}

function friendlyMessage(err, src, dest) {
  switch (err.code) {
    case 'ENOENT':
      return `I couldn't find "${src}". Please check that the path is correct.`;
    case 'ENOTDIR':
      return `"${src}" isn't a directory. This script only copies folders.`;
    case 'EACCES':
    case 'EPERM':
      return `I don't have permission to read or write one of these locations. Try checking the folder permissions.`;
    case 'ENOSPC':
      return `There isn't enough disk space to finish copying to "${dest}".`;
    case 'EEXIST':
      return `Something already exists at "${dest}" and I didn't want to overwrite it.`;
    case 'EINSIDE':
      return `The destination can't be inside the source folder. Please choose a different destination.`;
    case 'ERR_FS_CP_EINVAL':
      return `The source and destination are not compatible. Please double-check both paths.`;
    default:
      return `Something unexpected went wrong: ${err.message}`;
  }
}

async function main() {
  const [src, dest] = process.argv.slice(2);

  if (!src || !dest) {
    console.log('Usage: node copy-dir.js <source> <destination>');
    process.exit(1);
  }

  try {
    const { srcPath, destPath } = await copyDirectory(src, dest);
    console.log(`✅ Copied "${srcPath}" to "${destPath}" successfully!`);
  } catch (err) {
    console.error(`😕 Oops! ${friendlyMessage(err, src, dest)}`);
    process.exit(1);
  }
}

main();
