    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);

    if (entry.isDirectory()) {
      await copyDir(srcPath, destPath);
    } else if (entry.isSymbolicLink()) {
      const target = await fs.readlink(srcPath);
      await fs.symlink(target, destPath);
    } else {
      await fs.copyFile(srcPath, destPath);
    }
  }
}

function friendlyMessage(err, src, dest) {
  switch (err.code) {
    case 'ENOENT':
      return `Oops! I couldn't find "${err.path || src}". Please check the path and try again.`;
    case 'EACCES':
    case 'EPERM':
      return `I don't have permission to access "${err.path}". Try changing permissions or running with elevated rights.`;
    case 'ENOTDIR':
      return `"${err.path}" is not a directory, but I expected one.`;
    case 'EEXIST':
      return `Something already exists at "${err.path}", so I couldn't overwrite it.`;
    case 'ENOSPC':
      return `Your disk is full. Free up some space and try again.`;
    default:
      return `Something unexpected went wrong: ${err.message}`;
  }
}

async function main() {
  const [src, dest] = process.argv.slice(2);

  if (!src || !dest) {
    console.log('Usage: node copy-dir.js <source> <destination>');
    process.exit(1);
  }

  const srcResolved = path.resolve(src);
  const destResolved = path.resolve(dest);

  try {
    const stat = await fs.stat(srcResolved);
    if (!stat.isDirectory()) {
      console.log(`Hmm, "${src}" is a file, not a directory. Please give me a folder to copy.`);
      process.exit(1);
    }

    if (destResolved === srcResolved || destResolved.startsWith(srcResolved + path.sep)) {
      console.log("I can't copy a directory into itself. Please choose a different destination.");
      process.exit(1);
    }

    await copyDir(srcResolved, destResolved);
    console.log(`✅ Done! Copied "${src}" to "${dest}".`);
  } catch (err) {
    console.error(`😕 ${friendlyMessage(err, src, dest)}`);
    process.exit(1);
  }
}

main();
```

**Usage**

```bash
node copy-dir.js ./my-folder ./my-folder-backup
```

**Notes**

- Uses only built-in modules, so there's nothing to install.
- Checks up front that the source exists and is a directory, and prevents copying a folder into itself (which would recurse forever).
- Translates common error codes (missing path, permissions, full disk, etc.) into plain-language messages and falls back to the original error text for anything else.
- Exits with code 1 on failure, so it works properly in shell scripts.
- On Node 16.7+, you can replace `copyDir` with the built-in `fs.cp(src, dest, { recursive: true })`. I wrote the manual version so you can see and customize what happens at each step.

