Save this as `copy-directory.js`. It copies a directory and its contents, and prints a friendly error if the copy fails.

```js
const { cp, stat } = require('node:fs/promises');

async function main() {
  const [source, destination] = process.argv.slice(2);

  if (!source || !destination) {
    console.error('Usage: node copy-directory.js <source> <destination>');
    process.exitCode = 1;
    return;
  }

  try {
    if (!(await stat(source)).isDirectory()) {
      throw new Error(`"${source}" is not a directory.`);
    }

    await cp(source, destination, {
      recursive: true,
      force: false,
      errorOnExist: true,
    });

    console.log(`Copied "${source}" to "${destination}" successfully!`);
  } catch (error) {
    console.error(`Sorry, I couldn't finish copying the directory: ${error.message}`);
    process.exitCode = 1;
  }
}

main();
```

Run it with Node.js 22 or later:

```bash
node copy-directory.js ./photos ./photos-backup
```

