#!/usr/bin/env node

const { cp } = require("node:fs/promises");
const path = require("node:path");

async function main() {
  const [source, destination] = process.argv.slice(2);

  if (!source || !destination) {
    console.error("Usage: node copy-dir.js <source-directory> <destination-directory>");
    process.exitCode = 1;
    return;
