    let friendlyMessage =
      "Please check that the source exists and that you have permission to read and write these directories.";

    if (error.code === "ENOENT") {
      friendlyMessage = "The source directory or one of its parent directories could not be found.";
    } else if (error.code === "EACCES" || error.code === "EPERM") {
      friendlyMessage = "You don't have permission to access one of the directories.";
    } else if (error.code === "ENOSPC") {
      friendlyMessage = "There isn't enough disk space to complete the copy.";
    }

    console.error(`Oops! The directory couldn't be copied. ${friendlyMessage}`);
    console.error(`Details: ${error.message}`);
    process.exitCode = 1;
  }
}

main();
