# Reading a JSON Config File with Fallback Defaults

Here's a robust solution using Node.js:

```javascript
const fs = require('fs');
const path = require('path');

/**
 * Reads a JSON config file, returning defaults if missing or invalid.
 * @param {string} filePath - Path to the JSON config file.
 * @param {Object} defaults - Fallback configuration object.
 * @returns {Object} The parsed config or defaults.
 */
function loadConfig(filePath, defaults = {}) {
  try {
    if (!fs.existsSync(filePath)) {
      console.warn(`Config not found at "${filePath}". Using defaults.`);
      return { ...defaults };
    }

    const raw = fs.readFileSync(filePath, 'utf8');

    if (!raw.trim()) {
      console.warn(`Config file "${filePath}" is empty. Using defaults.`);
      return { ...defaults };
    }

    const parsed = JSON.parse(raw);

    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      console.warn(`Config file "${filePath}" is not a JSON object. Using defaults.`);
      return { ...defaults };
    }

    // Merge: defaults act as fallback for missing keys
    return { ...defaults, ...parsed };
  } catch (err) {
    console.warn(`Invalid config at "${filePath}" (${err.message}). Using defaults.`);
    return { ...defaults };
  }
}

module.exports = loadConfig;
```

## Usage

```javascript
const defaults = {
  port: 3000,
  host: 'localhost',
  debug: false
};

const config = loadConfig(path.join(__dirname, 'config.json'), defaults);

console.log(config.port); // 3000 if config.json is missing/broken
```

## Key features

- **Missing file** → returns defaults
- **Empty file** → returns defaults
- **Malformed JSON** → caught by `JSON.parse` in try/catch, returns defaults
- **Non-object JSON** (e.g., a bare string or array) → returns defaults
- **Partial config** → merged with defaults, so missing keys fall back gracefully
- **Never throws** — safe to call at startup

