const UserProfileSchema = z.object({
  id: z.number(),
  name: z.string(),
  email: z.string().email(),
  avatarUrl: z.string().url().optional(),
});

// Then parse instead of assert:
const parsed = UserProfileSchema.parse(await response.json());
return parsed;
```

This ensures the data actually matches the expected shape at runtime, not just at compile time.

```typescript
