  try {
    const response = await fetch(`https://api.example.com/users/${userId}`);

    if (!response.ok) {
      return null;
    }

    return (await response.json()) as UserProfile;
  } catch (error) {
    // Network error, JSON parse error, etc.
    return null;
  }
}
```

