    case "EISDIR":
      return `Expected a file but found a directory at "${err.path}".`;
    case "EMFILE":
      return `Too many files are open at once. Try closing other programs and retrying.`;
    default:
      return err.message || "Something unexpected went wrong.";
  }
}

