    case 'ENOSPC':
      return `Oh no, your disk is full! There's not enough space to complete the copy.`;
    case 'EISDIR':
      return `Something went wrong — it looks like a directory was expected where a file was found.`;
    default:
      return `Something unexpected went wrong: ${err.message}`;
  }
}

function main() {
  const [src, dest] = process.argv.slice(2);

  if (!src || !dest) {
