const fs = require('fs/promises');
const path = require('path');

async function copyDirRecursive(src, dest) {
  try {
    await fs.mkdir(dest, { recursive: true });
    const entries = await fs.readdir(src, { withFileTypes: true });

    for (const entry of entries) {
      const srcPath = path.join(src, entry.name);
      const destPath = path.join(dest, entry.name);

      if (entry.isDirectory()) {
        await copyDirRecursive(srcPath, destPath);
      } else {
        await fs.copyFile(srcPath, destPath);
      }
    }
  } catch (err) {
    console.log(`❌ Trouble copying "${src}": ${err.message}`);
    throw err;
  }
}

copyDirRecursive('./source', './destination')
  .then(() => console.log('✅ All done! Directory copied successfully.'))
  .catch(() => process.exit(1));
```

## Notes

- **`fs.cp` with `recursive: true`** is the modern, built-in way to copy directories — it preserves subdirectories and files.
- Add `{ force: false }` to the options if you don't want to overwrite an existing destination.
- The error handler covers common cases (missing paths, permission issues, full disks) so users get helpful feedback instead of a raw stack trace.
- If you need to filter files (e.g., skip `node_modules`), pass a `filter` option: `fs.cp(src, dest, { recursive: true, filter: (f) => !f.includes('node_modules') })`.

Here's a Node.js script that copies a directory recursively with friendly error handling:

```javascript
#!/usr/bin/env node
/**
 * copy-dir.js — Copies a directory recursively with friendly error messages.
 *
 * Usage: node copy-dir.js <source> <destination>
 */

const fs = require("fs/promises");
const path = require("path");

async function copyDirectory(source, destination) {
  try {
    await fs.cp(source, destination, { recursive: true });
    console.log(`✅ Success! Copied "${source}" to "${destination}".`);
  } catch (err) {
    handleError(err, source, destination);
    process.exit(1);
  }
}

function handleError(err, source, destination) {
  switch (err.code) {
    case "ENOENT":
      console.error(`😊 Oops! The source directory "${source}" doesn't exist.`);
      console.error("   Double-check the path and try again?");
      break;
    case "ENOTDIR":
      console.error(`😊 Hmm, "${source}" is a file, not a directory.`);
      console.error("   This script only copies folders.");
      break;
    case "EACCES":
    case "EPERM":
      console.error(`😊 It looks like we don't have permission to access "${source}".`);
      console.error("   Try checking the folder's permissions or run with elevated access.");
      break;
    case "ENOSPC":
      console.error(`😊 There's not enough disk space to copy to "${destination}".`);
      console.error("   Consider freeing up some space first.");
      break;
    default:
      console.error(`😊 Something went wrong while copying: ${err.message}`);
      console.error("   (Full details below, just in case they help.)");
      console.error(err);
  }
}

async function main() {
  const [source, destination] = process.argv.slice(2);

  if (!source || !destination) {
    console.error("😊 You need to provide two paths:");
    console.error("   node copy-dir.js <source-directory> <destination-directory>");
    process.exit(1);
  }

  const absSource = path.resolve(source);
  const absDest = path.resolve(destination);

  if (absSource === absDest) {
    console.error('😊 Source and destination are the same — nothing to copy!');
    process.exit(1);
  }

  // Prevent copying a directory into itself (e.g., ./a into ./a/b)
  if (absDest.startsWith(absSource + path.sep)) {
    console.error(`😊 You can't copy a folder into itself.`);
    console.error(`   "${absDest}" is inside "${absSource}".`);
    process.exit(1);
  }

  await copyDirectory(absSource, absDest);
}

main();
```

**Usage:**

```bash
node copy-dir.js ./my-photos ./backup-photos
```

**Key features:**

- Uses `fs.cp()` with `{ recursive: true }` (available in Node 16.7+), which handles nested folders and files.
- Catches common error codes (`ENOENT`, `EACCES`, `ENOSPC`, etc.) and translates them into plain-English messages.
- Guards against copying a directory into itself, which would loop forever.
- Exits with a non-zero status code on failure, so shell scripts can detect the failure.

If you're on an older Node version (pre-16.7), let me know and I can provide a version that manually walks the directory tree with `fs.readdir` and `fs.mkdir`.

# Reading JSON Config with Defaults

Here's a robust implementation that handles missing files, invalid JSON, and partial configs (deep-merging with defaults):

```javascript
const fs = require('fs/promises');
const path = require('path');

/**
 * Deep-merges source into target. Arrays and primitives from source
 * replace those in target; plain objects are merged recursively.
 */
function deepMerge(target, source) {
  if (source === null || typeof source !== 'object' || Array.isArray(source)) {
    return source === undefined ? target : source;
  }
  const result = { ...target };
  for (const key of Object.keys(source)) {
    const srcVal = source[key];
    const tgtVal = target?.[key];
    if (
      srcVal && typeof srcVal === 'object' && !Array.isArray(srcVal) &&
      tgtVal && typeof tgtVal === 'object' && !Array.isArray(tgtVal)
    ) {
      result[key] = deepMerge(tgtVal, srcVal);
    } else {
      result[key] = srcVal;
    }
  }
  return result;
}

/**
 * Loads a JSON config file. Returns a deep-merged copy of `defaults`
 * if the file is missing, unreadable, or contains invalid JSON.
 *
 * @param {string} filePath - Path to the JSON config file.
 * @param {object} defaults - Default configuration values.
 * @returns {Promise<object>} The resolved configuration.
 */
async function loadConfig(filePath, defaults = {}) {
  try {
    const raw = await fs.readFile(path.resolve(filePath), 'utf8');
    const parsed = JSON.parse(raw);

    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      console.warn(`Config at ${filePath} is not a JSON object; using defaults.`);
      return structuredClone(defaults);
    }

    return deepMerge(defaults, parsed);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.info(`Config file ${filePath} not found; using defaults.`);
    } else if (err instanceof SyntaxError) {
      console.warn(`Config file ${filePath} contains invalid JSON; using defaults.`);
    } else {
      console.warn(`Failed to load config ${filePath}: ${err.message}; using defaults.`);
    }
    return structuredClone(defaults);
  }
}

module.exports = { loadConfig, deepMerge };
```

## Usage

```javascript
