    raw = await fs.readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      logger(`Config file not found at "${filePath}", using defaults.`);
    } else {
      logger(`Could not read config file "${filePath}": ${err.message}`);
    }
    return structuredClone(defaults);
  }

