  if (raw.trim() === '') {
    logger(`Config file "${filePath}" is empty, using defaults.`);
    return structuredClone(defaults);
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    logger(`Invalid JSON in "${filePath}": ${err.message}. Using defaults.`);
    return structuredClone(defaults);
  }

  // Reject non-object roots (arrays, null, primitives)
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    logger(`Config in "${filePath}" is not a JSON object. Using defaults.`);
    return structuredClone(defaults);
  }

  return merge ? deepMerge(structuredClone(defaults), parsed) : parsed;
}

/**
 * Recursively merges `source` into `target`. Arrays and primitives are replaced.
 */
function deepMerge(target, source) {
  for (const key of Object.keys(source)) {
    const sv = source[key];
    const tv = target[key];
    if (
      sv && typeof sv === 'object' && !Array.isArray(sv) &&
      tv && typeof tv === 'object' && !Array.isArray(tv)
    ) {
      target[key] = deepMerge(tv, sv);
    } else {
      target[key] = sv;
    }
  }
  return target;
}

module.exports = { loadConfig, deepMerge };
```

