## Behavior summary

| Situation | Result |
|---|---|
| File missing (`ENOENT`) | Returns a clone of `defaults` |
| File unreadable (permissions, etc.) | Returns a clone of `defaults` |
| Empty / whitespace-only file | Returns a clone of `defaults` |
| Malformed JSON | Returns a clone of `defaults` |
| Valid JSON but not an object (array, `null`, `"foo"`) | Returns a clone of `defaults` |
| Valid JSON object | Deep-merged over `defaults` (unless `merge: false`) |

## Notes on design choices

- **`structuredClone(defaults)`** — returns a fresh copy each call so callers can't accidentally mutate the shared defaults object.
- **Deep merge** — lets a partial config file override only the keys it specifies, while nested defaults (like `db.poolSize`) survive.
- **Arrays are replaced, not merged** — merging arrays element-wise is almost never what you want for config.
- **`logger` is injectable** — swap in your own logger, or pass `() => {}` to silence warnings.
- **Async by default** — uses `fs/promises`. If you need a synchronous version, replace `await fs.readFile(...)` with `fs.readFileSync(...)` and drop the `async`/`Promise` bits.

```javascript
const fs = require('fs/promises');

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// Deep-merge loaded values over defaults so nested defaults survive partial configs
function mergeWithDefaults(defaults, loaded) {
  const result = structuredClone(defaults);
  if (!isPlainObject(loaded)) return result;

  for (const [key, value] of Object.entries(loaded)) {
    result[key] =
      isPlainObject(value) && isPlainObject(result[key])
        ? mergeWithDefaults(result[key], value)
        : value;
  }
  return result;
}

/**
 * Read a JSON config file.
 * Returns a copy of `defaults` if the file is missing, unreadable as JSON,
 * or contains something other than a JSON object.
 */
async function loadConfig(filePath, defaults = {}) {
  let raw;
  try {
    raw = await fs.readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return structuredClone(defaults); // missing file
    throw err; // permission errors etc. are real problems — surface them
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return structuredClone(defaults); // malformed JSON
  }

  if (!isPlainObject(parsed)) return structuredClone(defaults); // e.g. `[1,2,3]` or `null`

  return mergeWithDefaults(defaults, parsed);
}
```

Usage:

```javascript
