- **Sync version:** Swap `fs/promises` for `fs` and drop `async`/`await` if you need it at module top-level without ESM top-level await.

- **Schema validation:** For stricter guarantees, pipe the parsed object through something like [Zod](https://zod.dev) or [ajv](https://ajv.js.org) and catch the validation error the same way.

- **Distinguishing errors:** If you want missing files to be silent but corrupt files loud, check `err.code === 'ENOENT'` inside the first catch before deciding whether to call `onError`.

# Reading JSON Config with Defaults

Here's a robust Node.js function that reads a JSON config file and falls back to defaults when the file is missing, unreadable, or contains invalid JSON:

```javascript
const fs = require('fs/promises');
const path = require('path');

/**
 * Load a JSON config file, falling back to defaults on any failure.
 *
 * @param {string} filePath - Path to the JSON config file.
 * @param {object} defaults - Default values to use / merge with.
 * @param {object} [options]
 * @param {boolean} [options.deepMerge=false] - Recursively merge nested objects.
 * @param {(err: Error) => void} [options.onError] - Optional error callback.
 * @returns {Promise<object>} The merged config.
 */
async function loadConfig(filePath, defaults = {}, options = {}) {
  const { deepMerge = false, onError } = options;

  let raw;
  try {
    raw = await fs.readFile(filePath, 'utf8');
  } catch (err) {
    // File missing or unreadable — silently fall back to defaults.
    if (err.code !== 'ENOENT' && onError) onError(err);
    return { ...defaults };
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    if (onError) onError(err);
    return { ...defaults };
  }

  // Guard against valid JSON that isn't a plain object (e.g. `null`, `[]`, `"hi"`).
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    if (onError) onError(new Error(`Config at ${filePath} is not a JSON object`));
    return { ...defaults };
  }

  return deepMerge ? mergeDeep(defaults, parsed) : { ...defaults, ...parsed };
}

/**
 * Recursively merge `source` into `target` (source wins).
 * Plain objects are merged; arrays and primitives are replaced.
 */
function mergeDeep(target, source) {
  const out = { ...target };
  for (const [key, value] of Object.entries(source)) {
    const existing = out[key];
    if (
      value && typeof value === 'object' && !Array.isArray(value) &&
      existing && typeof existing === 'object' && !Array.isArray(existing)
    ) {
      out[key] = mergeDeep(existing, value);
    } else {
      out[key] = value;
    }
  }
  return out;
}

module.exports = { loadConfig, mergeDeep };
```

## Usage

```javascript
