# Safe JSON Config Loader

Here's a robust implementation that handles missing files, invalid JSON, and partial configs by merging with defaults:

```javascript
const fs = require('fs');
const path = require('path');

/**
 * Reads a JSON config file and returns a validated config object.
 * Falls back to defaults if the file is missing, unreadable, or malformed.
 *
 * @param {string} filePath - Path to the JSON config file.
 * @param {object} defaults - Default config values.
 * @param {object} [options]
 * @param {boolean} [options.deep=true] - Deep-merge user config into defaults.
 * @param {(config: object) => boolean} [options.validate] - Optional validator.
 * @returns {object} The resolved config object.
 */
function loadConfig(filePath, defaults, options = {}) {
  const { deep = true, validate } = options;
  const resolvedPath = path.resolve(filePath);

  let userConfig = {};

  try {
    const raw = fs.readFileSync(resolvedPath, 'utf8');
    userConfig = JSON.parse(raw);

    // Reject non-object JSON (e.g. `null`, `[]`, `"string"`)
    if (userConfig === null || typeof userConfig !== 'object' || Array.isArray(userConfig)) {
      throw new TypeError('Config root must be a JSON object');
    }
  } catch (err) {
    // ENOENT, EACCES, SyntaxError, TypeError — all fall back to defaults
    console.warn(`[config] Using defaults for "${filePath}": ${err.message}`);
    return clone(defaults);
  }

  const merged = deep ? deepMerge(clone(defaults), userConfig) : { ...defaults, ...userConfig };

  if (typeof validate === 'function' && !validate(merged)) {
    console.warn(`[config] Validation failed for "${filePath}", using defaults.`);
    return clone(defaults);
  }

  return merged;
}

/* ---------- helpers ---------- */

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function clone(obj) {
  // structuredClone is available in Node 17+ and modern browsers
  if (typeof structuredClone === 'function') return structuredClone(obj);
  return JSON.parse(JSON.stringify(obj));
}

function deepMerge(target, source) {
  for (const key of Object.keys(source)) {
    const sVal = source[key];
    const tVal = target[key];

    if (isPlainObject(sVal) && isPlainObject(tVal)) {
      target[key] = deepMerge(tVal, sVal);
    } else if (sVal !== undefined) {
      target[key] = sVal;
    }
  }
  return target;
}

module.exports = { loadConfig };
```

## Usage

