# Reading JSON Config with Fallback Defaults

Here's a robust Node.js solution that reads a JSON config file, merges it with defaults, and gracefully handles missing/invalid files:

```javascript
const fs = require('fs').promises;
const path = require('path');

/**
 * Deep-merges user config over defaults (user values win).
 * Arrays and primitives are replaced, not merged.
 */
function deepMerge(defaults, overrides) {
  if (
    typeof defaults !== 'object' || defaults === null ||
    typeof overrides !== 'object' || overrides === null ||
    Array.isArray(defaults) || Array.isArray(overrides)
  ) {
    return overrides !== undefined ? overrides : defaults;
  }

  const result = { ...defaults };
  for (const key of Object.keys(overrides)) {
    result[key] = key in defaults
      ? deepMerge(defaults[key], overrides[key])
      : overrides[key];
  }
  return result;
}

/**
 * Loads a JSON config file. Falls back to `defaults` on any failure
 * (missing file, unreadable, invalid JSON, wrong root type).
 *
 * @param {string} filePath - Path to the JSON config file.
 * @param {object} defaults - Default configuration values.
 * @param {object} [options]
 * @param {boolean} [options.silent=false] - Suppress warnings.
 * @returns {Promise<object>} Merged configuration.
 */
async function loadConfig(filePath, defaults = {}, options = {}) {
  const { silent = false } = options;
  const warn = (msg) => !silent && console.warn(`[config] ${msg}`);

  let raw;
  try {
    raw = await fs.readFile(path.resolve(filePath), 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      warn(`"${filePath}" not found — using defaults.`);
    } else {
      warn(`Could not read "${filePath}" (${err.code}) — using defaults.`);
    }
    return { ...defaults };
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    warn(`"${filePath}" is not valid JSON (${err.message}) — using defaults.`);
    return { ...defaults };
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    warn(`"${filePath}" root must be an object — using defaults.`);
    return { ...defaults };
  }

  return deepMerge(defaults, parsed);
}

module.exports = { loadConfig, deepMerge };
```

## Usage

```javascript
