const UserProfileSchema = z.object({
  id: z.string(),
  name: z.string(),
  email: z.string().email(),
  avatarUrl: z.string().url().optional(),
});

async function fetchUserProfile(userId: string): Promise<UserProfile | null> {
  try {
    const response = await fetch(`/api/users/${encodeURIComponent(userId)}`);
    if (!response.ok) return null;

    const parsed = UserProfileSchema.safeParse(await response.json());
    return parsed.success ? parsed.data : null;
  } catch {
    return null;
  }
}
```

# Fetch User Profile with Null Fallback

```typescript
interface UserProfile {
  id: string;
  name: string;
  email: string;
  avatarUrl?: string;
}

async function fetchUserProfile(userId: string): Promise<UserProfile | null> {
  try {
    const response = await fetch(`https://api.example.com/users/${userId}`, {
      method: "GET",
      headers: {
        Accept: "application/json",
      },
    });

    if (!response.ok) {
      console.error(
        `Failed to fetch user ${userId}: ${response.status} ${response.statusText}`
      );
      return null;
    }

    const data: unknown = await response.json();

    // Basic runtime validation — TS types are erased at runtime,
    // so we can't fully trust `data` to match UserProfile.
    if (!isUserProfile(data)) {
      console.error(`Invalid user profile shape for user ${userId}`);
      return null;
    }

    return data;
  } catch (error) {
    // Network errors, JSON parse failures, aborts, etc.
    console.error(`Error fetching user ${userId}:`, error);
    return null;
  }
}

function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.name === "string" &&
    typeof v.email === "string" &&
    (v.avatarUrl === undefined || typeof v.avatarUrl === "string")
  );
}
```

## Usage

```typescript
const profile = await fetchUserProfile("user-123");
if (profile === null) {
  // handle missing profile
} else {
  console.log(profile.name);
}
```

## Notes on the design

- **Return type `Promise<UserProfile | null>`** — the caller is forced by the type system to handle the failure case.
- **Two failure paths handled**:
  1. **HTTP errors** (`response.ok === false`) — a 404 or 500 does *not* throw with `fetch`, so you must check `response.ok` explicitly.
  2. **Exceptions** — `fetch` only rejects on network-level failures (DNS, offline, CORS). The `try/catch` also covers `response.json()` throwing on malformed bodies.
- **Runtime validation** — TypeScript types are compile-time only. The `isUserProfile` type guard protects against a backend returning unexpected JSON (e.g., an error payload with a 200 status).
- **No error propagation** — per the requirement, failures are logged and swallowed, returning `null`. If you later want callers to distinguish *why* it failed, switch to returning a discriminated union like `{ ok: true; data: UserProfile } | { ok: false; error: Error }`.

## Variant: using `AbortSignal` for timeouts

If you want the request to fail fast rather than hang indefinitely:

```typescript
async function fetchUserProfile(
  userId: string,
  timeoutMs = 5000
): Promise<UserProfile | null> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(`https://api.example.com/users/${userId}`, {
      signal: controller.signal,
    });
    if (!response.ok) return null;
    const data: unknown = await response.json();
    return isUserProfile(data) ? data : null;
  } catch {
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}
```

