# Node.js Directory Copy Script

Here's a script that copies a directory recursively and handles errors gracefully with friendly messages:

```javascript
#!/usr/bin/env node

const fs = require('fs').promises;
const path = require('path');

/**
 * Copy a directory recursively from source to destination.
 * @param {string} source - Path to the source directory.
 * @param {string} destination - Path to the destination directory.
 */
async function copyDirectory(source, destination) {
  const src = path.resolve(source);
  const dest = path.resolve(destination);

  // Sanity check: source must exist and be a directory
  let stats;
  try {
    stats = await fs.stat(src);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new FriendlyError(
        `Hmm, I couldn't find the source directory at "${src}". ` +
        `Double-check the path and try again.`
      );
    }
    throw new FriendlyError(
      `I had trouble looking at "${src}". The system said: ${err.message}`
    );
  }

  if (!stats.isDirectory()) {
    throw new FriendlyError(
      `"${src}" isn't a directory — it looks like it might be a file. ` +
      `I can only copy directories.`
    );
  }

  // Prevent copying a directory into itself
  if (dest === src || dest.startsWith(src + path.sep)) {
    throw new FriendlyError(
      `I can't copy "${src}" into itself ("${dest}"). ` +
      `Please pick a destination outside the source folder.`
    );
  }

  // Warn if destination already exists
  try {
    await fs.access(dest);
    console.warn(
      `Heads up: "${dest}" already exists. I'll merge the contents in.`
    );
  } catch {
    // Destination doesn't exist — that's fine.
  }

  // Do the copy (Node 16.7+)
  try {
    await fs.cp(src, dest, {
      recursive: true,
      errorOnExist: false,
      force: true,
    });
  } catch (err) {
    if (err.code === 'EACCES' || err.code === 'EPERM') {
      throw new FriendlyError(
        `I don't have permission to write to "${dest}". ` +
        `Try running with different permissions or pick another location.`
      );
    }
    if (err.code === 'ENOSPC') {
      throw new FriendlyError(
        `Looks like we ran out of disk space while copying. ` +
        `Free up some room and try again.`
      );
    }
    throw new FriendlyError(
      `Something went wrong while copying: ${err.message}`
    );
  }
}

/**
 * A custom error type so we can distinguish "friendly" errors
 * (already written for humans) from unexpected ones.
 */
class FriendlyError extends Error {
  constructor(message) {
    super(message);
    this.name = 'FriendlyError';
  }
}

// --- CLI entry point ---
async function main() {
  const [source, destination] = process.argv.slice(2);

  if (!source || !destination) {
    console.log(
      'Usage: node copy-dir.js <source-directory> <destination-directory>'
    );
    console.log('Example: node copy-dir.js ./photos ./backup/photos');
    process.exit(1);
  }

  console.log(`Copying "${source}" → "${destination}" ...`);

  try {
    await copyDirectory(source, destination);
    console.log(`All done! Your files are safely in "${destination}".`);
  } catch (err) {
    if (err instanceof FriendlyError) {
      console.error(`\nOops! ${err.message}`);
    } else {
      console.error(
        `\nWell, that was unexpected. Here's what happened:\n${err.stack}`
      );
    }
    process.exit(1);
  }
}

main();
```

## How it works

1. **`fs.cp` with `recursive: true`** — Node's built-in recursive copy (available in Node 16.7+). No external dependencies needed.
2. **Pre-flight checks** — Verifies the source exists, is a directory, and isn't being copied into itself.
3. **Friendly error mapping** — Common failure modes (`ENOENT`, `EACCES`, `ENOSPC`) get human-readable messages instead of raw stack traces.
4. **`FriendlyError` class** — Distinguishes expected errors (already phrased nicely) from unexpected ones (which get a full stack trace for debugging).

## Usage

```bash
