# Directory Copy Script

Here's a Node.js script that recursively copies a directory and handles errors gracefully:

```javascript
#!/usr/bin/env node
'use strict';

const fs = require('fs').promises;
const path = require('path');

/**
 * Recursively copies a directory from `src` to `dest`.
 * @param {string} src  - Source directory path
 * @param {string} dest - Destination directory path
 */
async function copyDirectory(src, dest) {
  const stats = await fs.stat(src);

  if (!stats.isDirectory()) {
    throw new Error(`"${src}" is not a directory.`);
  }

  await fs.mkdir(dest, { recursive: true });

  const entries = await fs.readdir(src, { withFileTypes: true });

  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);

    if (entry.isDirectory()) {
      await copyDirectory(srcPath, destPath);
    } else if (entry.isSymbolicLink()) {
      const linkTarget = await fs.readlink(srcPath);
      await fs.symlink(linkTarget, destPath).catch(() => {
        // Ignore if the symlink already exists
      });
    } else if (entry.isFile()) {
      await fs.copyFile(srcPath, destPath);
    }
    // Skip sockets, FIFOs, devices — they don't copy cleanly
  }
}

/**
 * Turns a raw error into a friendlier message.
 */
function friendlyMessage(err, src, dest) {
  switch (err.code) {
    case 'ENOENT':
      return `😕 Hmm, I couldn't find "${src}". Double-check the path and try again.`;
    case 'EACCES':
    case 'EPERM':
      return `🔒 I don't have permission to read from or write to that location. Try running with different permissions.`;
    case 'ENOSPC':
      return `💾 Not enough disk space to finish copying to "${dest}".`;
    case 'EEXIST':
      return `📁 Something already exists at "${dest}" that I can't overwrite.`;
    case 'EISDIR':
    case 'ENOTDIR':
      return `🤔 The path "${src}" or "${dest}" isn't quite what I expected (file vs. directory mismatch).`;
    case 'ELOOP':
      return `🌀 I got stuck following a circular symlink while copying.`;
    default:
      return `⚠️  Something went wrong while copying: ${err.message}`;
  }
}

async function main() {
  const [, , src, dest] = process.argv;

  if (!src || !dest) {
    console.log('Usage: node copy-dir.js <source-dir> <dest-dir>');
    process.exit(1);
  }

  const source = path.resolve(src);
  const destination = path.resolve(dest);

  try {
    await copyDirectory(source, destination);
    console.log(`✅ Copied "${source}" → "${destination}" successfully!`);
  } catch (err) {
    console.error(friendlyMessage(err, source, destination));
    process.exit(1);
  }
}

main();
```

## Usage

```bash
node copy-dir.js ./my-project ./backups/my-project
```

## How it works

1. **Recursive walk** – `copyDirectory` reads each entry and descends into subdirectories.
2. **Symlinks** – Preserved with `fs.symlink` (broken links won't crash the script).
3. **File copy** – Uses `fs.copyFile` for efficient byte-for-byte copying.
4. **Friendly errors** – `friendlyMessage` maps common `err.code` values (`ENOENT`, `EACCES`, `ENOSPC`, …) to human-readable messages with a helpful hint.

