    if (err.code !== 'ENOENT') throw err;
    // Destination doesn't exist — that's fine, we'll create it.
  }

  // Create the destination directory (recursive so nested paths work)
  await fs.mkdir(dest, { recursive: true });

  // Read entries from the source
  const entries = await fs.readdir(src, { withFileTypes: true });

  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);

    if (entry.isDirectory()) {
      await copyDir(srcPath, destPath);      // Recurse into subfolders
    } else if (entry.isSymbolicLink()) {
      // Preserve symlinks rather than following them
      const linkTarget = await fs.readlink(srcPath);
      await fs.symlink(linkTarget, destPath);
    } else {
      await fs.copyFile(srcPath, destPath);  // Regular file
    }
  }
}

// --- CLI entry point ---------------------------------------------------------

async function main() {
  const [src, dest] = process.argv.slice(2);

  if (!src || !dest) {
    console.error('Usage: node copy-dir.js <source-folder> <destination-folder>');
    process.exit(1);
  }

  const srcAbs = path.resolve(src);
  const destAbs = path.resolve(dest);

  console.log(`📁 Copying "${srcAbs}" → "${destAbs}" ...`);

  try {
    await copyDir(srcAbs, destAbs);
    console.log('✅ All done! Your folder was copied successfully.');
  } catch (err) {
