  const header = '😕  Oops — the copy didn\'t work.';

  switch (err.code) {
    case 'ENOENT':
      console.error(
        `${header}\n` +
        `   I couldn't find "${src}".\n` +
        `   Double-check the path and try again.`
      );
      break;

    case 'EACCES':
    case 'EPERM':
      console.error(
        `${header}\n` +
        `   I don't have permission to read "${src}" or write to "${dest}".\n` +
        `   Try running with different permissions or pick another destination.`
      );
      break;

    case 'ENOSPC':
      console.error(
        `${header}\n` +
