        `   Free up some room and try again.`
      );
      break;

    case 'EEXIST':
    case 'ERR_FS_CP_EEXIST':
      console.error(
        `${header}\n` +
        `   Something already exists at "${dest}".\n` +
        `   Remove it first, or choose a different destination.`
      );
