      throw err;
    }

    if (!stats.isDirectory()) {
      throw new FriendlyError(
        `"${src}" isn't a directory — it looks like a file. I need a folder to copy.`
      );
    }

    // Don't let someone copy a directory into itself
    if (destination.startsWith(source + path.sep)) {
      throw new FriendlyError(
        `Oops — I can't copy "${src}" into a folder inside itself. Pick a different destination.`
      );
    }

    // Do the recursive copy (Node 16.7+)
    await fs.cp(source, destination, { recursive: true });

    console.log(`✅ All done! Copied "${src}" → "${dest}"`);
  } catch (err) {
    if (err instanceof FriendlyError) {
      console.error(`😕 ${err.message}`);
    } else {
      switch (err.code) {
        case 'EACCES':
        case 'EPERM':
          console.error(
            `🔒 I don't have permission to copy "${src}". Try running with different permissions.`
          );
          break;
        case 'ENOSPC':
          console.error(
            `💾 Not enough disk space to copy "${src}". Free up some room and try again.`
          );
          break;
        case 'EEXIST':
          console.error(
            `📁 The destination "${dest}" already exists and can't be overwritten.`
          );
          break;
        case 'ENOTDIR':
          console.error(
            `🤔 One of the paths I was given isn't a directory. Check "${src}" and "${dest}".`
          );
          break;
        case 'EROFS':
          console.error(
            `📖 The destination is on a read-only filesystem — I can't write there.`
          );
          break;
        default:
          console.error(
            `❌ Something went wrong while copying: ${err.message}`
          );
      }
    }
    process.exitCode = 1;
  }
}

// Custom error type so we can distinguish "friendly" messages from unexpected ones
class FriendlyError extends Error {}

// ----- CLI entry point -----
