A small Node.js script that recursively copies a directory and turns any failure into a friendly, human-readable message (with the raw error available via `DEBUG=1`).

```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');

/**
 * Map common system error codes to friendly, non-scary messages.
 * Each entry is a function so we can interpolate the offending path.
 */
const FRIENDLY_MESSAGES = {
  ENOENT:  (p) => `I couldn't find "${p}". Double-check the path and try again.`,
  EACCES:  (p) => `I don't have permission to read or write "${p}". You may need to adjust permissions or run with elevated privileges.`,
  EPERM:   (p) => `The operating system blocked access to "${p}".`,
  ENOSPC:  ()  => `There's no space left on the disk. Free up some room and try again.`,
  EEXIST:  (p) => `"${p}" already exists and I can't overwrite it.`,
  EISDIR:  (p) => `"${p}" is a directory, but I expected a file.`,
  ENOTDIR: (p) => `"${p}" is a file, but I expected a directory.`,
  EMFILE:  ()  => `Too many files are open at once. Close some apps and retry.`,
  EROFS:   (p) => `"${p}" is on a read-only filesystem.`,
  EBUSY:   (p) => `"${p}" is busy — another program might be using it.`,
};

function friendlyError(err) {
  const make = FRIENDLY_MESSAGES[err.code];
  if (make) return make(err.path || 'that path');
  return `Something unexpected went wrong: ${err.message}`;
}

/** Small helper so we can throw errors that carry a `code` and `path`. */
function fail(code, pathLike, message) {
  const e = new Error(message);
  e.code = code;
  e.path = pathLike;
  return e;
}

async function copyDirectory(src, dest) {
  const srcPath  = path.resolve(src);
  const destPath = path.resolve(dest);

  if (srcPath === destPath) {
    throw fail('EEXIST', srcPath, 'Source and destination are the same — nothing to do!');
  }

  // 1. Verify the source exists and is actually a directory.
  let stat;
  try {
    stat = await fs.stat(srcPath);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw fail('ENOENT', srcPath, `Source directory not found: ${srcPath}`);
    }
    throw err;
  }
  if (!stat.isDirectory()) {
    throw fail('ENOTDIR', srcPath, `Source is not a directory: ${srcPath}`);
  }

  // 2. Refuse to copy a directory into itself (would recurse forever).
  const rel = path.relative(srcPath, destPath);
  if (rel && !rel.startsWith('..') && !path.isAbsolute(rel)) {
    throw fail('EINVAL', destPath, `I can't copy "${srcPath}" into itself.`);
  }

  // 3. Do the recursive copy (Node 16.7+).
  await fs.cp(srcPath, destPath, {
    recursive: true,
    force: true,          // overwrite existing files
    errorOnExist: false,  // don't blow up if dest already has files
  });

  return destPath;
}

async function main() {
  const [, , src, dest] = process.argv;

  if (!src || !dest) {
    console.error('Usage: node copy-dir.js <source-dir> <destination-dir>');
    process.exitCode = 1;
    return;
  }

  try {
    const out = await copyDirectory(src, dest);
    console.log(`✅ All done! Copied "${src}" to "${out}".`);
  } catch (err) {
    console.error(`😕 Oops — ${friendlyError(err)}`);
    if (process.env.DEBUG) {
      console.error('\n--- raw error (DEBUG=1) ---');
      console.error(err);
    }
    process.exitCode = 1;
  }
}

main();
```

