const fs = require('node:fs/promises');
const path = require('node:path');

/**
 * Copy a directory recursively with friendly error handling.
 * @param {string} source - Path to the source directory.
 * @param {string} destination - Path to the destination directory.
 */
async function copyDirectory(source, destination) {
  const src = path.resolve(source);
  const dest = path.resolve(destination);

  try {
    // Ensure the source exists and is actually a directory.
    const stats = await fs.stat(src);
    if (!stats.isDirectory()) {
      throw Object.assign(new Error('not-a-directory'), { code: 'ENOTDIR' });
    }

    // Refuse to copy a directory into itself.
    const rel = path.relative(src, dest);
    if (rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel))) {
      throw Object.assign(new Error('copy-into-itself'), { code: 'EINVAL' });
    }

    // Recursively copy. `force: false` would fail on existing files;
    // we keep the default (overwrite) but you can change that here.
    await fs.cp(src, dest, {
      recursive: true,
      errorOnExist: false,
      preserveTimestamps: true,
    });

    console.log(`✅ Copied "${src}" → "${dest}"`);
  } catch (err) {
    printFriendlyError(err, src, dest);
    process.exitCode = 1;
  }
}

/**
 * Translate common filesystem error codes into human-friendly messages.
 */
function printFriendlyError(err, src, dest) {
  const messages = {
    ENOENT: `😕 I couldn't find the source directory: "${src}". Double-check the path and try again.`,
    ENOTDIR: `😕 "${src}" isn't a directory — I can only copy folders, not files.`,
    EACCES: `🔒 Permission denied. I don't have access to read from "${src}" or write to "${dest}".`,
    EPERM: `🔒 The operating system blocked the operation. Try running with elevated permissions.`,
    ENOSPC: `💾 Out of disk space while copying to "${dest}". Free up some room and retry.`,
    EEXIST: `📁 Something already exists at "${dest}" and I wasn't allowed to overwrite it.`,
    EINVAL: `🤔 That copy doesn't make sense — you can't copy a directory into itself.`,
    EROFS: `🧊 The destination "${dest}" is on a read-only filesystem.`,
  };

  const friendly = messages[err.code];
  if (friendly) {
    console.error(friendly);
  } else {
    console.error(`💥 Something went wrong while copying "${src}" → "${dest}":`);
    console.error(`   ${err.code || err.name || 'Error'}: ${err.message}`);
  }
}

// ---- CLI entry point ----
if (require.main === module) {
  const [, , source, destination] = process.argv;

  if (!source || !destination) {
    console.error('Usage: node copy-dir.js <source-dir> <destination-dir>');
    process.exit(1);
  }

  copyDirectory(source, destination);
}

module.exports = { copyDirectory };
