const fs = require('fs').promises;
const path = require('path');

async function copyDirectory(source, destination) {
  // Check source exists
  try {
    await fs.access(source);
  } catch {
    console.error(`😕 Hmm, I couldn't find the source folder: "${source}"`);
    console.error('   Double-check the path and try again.');
    process.exit(1);
  }

  // Make sure source is actually a directory
  const stats = await fs.stat(source);
  if (!stats.isDirectory()) {
    console.error(`😕 "${source}" is a file, not a folder.`);
    console.error('   This script only copies directories.');
    process.exit(1);
  }

  // Check destination doesn't already exist
  try {
    await fs.access(destination);
    console.error(`😕 The destination "${destination}" already exists.`);
    console.error('   Please pick a different location or remove it first.');
    process.exit(1);
  } catch {
    // Good — destination is free
  }

  try {
    await fs.cp(source, destination, { recursive: true });
    console.log(`✅ All done! Copied "${source}" → "${destination}"`);
  } catch (err) {
    console.error('😕 Oops, something went wrong while copying:');
    console.error(`   ${err.message}`);

    if (err.code === 'EACCES') {
      console.error('   Looks like a permissions issue — try running with different rights.');
    } else if (err.code === 'ENOSPC') {
      console.error('   It seems the disk is full.');
    } else if (err.code === 'EMFILE' || err.code === 'ENFILE') {
      console.error('   Too many files open at once — try again, or increase the ulimit.');
    }

    process.exit(1);
  }
}

// --- Entry point ---
const [, , source, destination] = process.argv;

if (!source || !destination) {
  console.log('Usage: node copy-dir.js <source> <destination>');
  console.log('Example: node copy-dir.js ./photos ./backup/photos');
  process.exit(1);
}

copyDirectory(path.resolve(source), path.resolve(destination));
```

## How to use it

```bash
node copy-dir.js ./my-folder ./my-folder-backup
```

## What it handles

| Situation | Friendly response |
|---|---|
| Source doesn't exist | `😕 Hmm, I couldn't find the source folder...` |
| Source is a file | `😕 "..." is a file, not a folder.` |
| Destination already exists | `😕 The destination "..." already exists.` |
| Permission denied | Suggests checking rights |
| Disk full | Mentions the disk is full |
| Too many open files | Suggests `ulimit` |

## Notes

- Uses `fs.cp` (Node **16.7+**), which supports recursive copies natively — no dependencies needed.
- If you're on an older Node version, swap the `fs.cp` call for [`fs-extra`](https://www.npmjs.com/package/fs-extra)'s `copy`, which also supports recursive copying with a similar API.
- The script resolves both paths with `path.resolve` so relative paths work as expected.
- It refuses to overwrite an existing destination to keep things safe — remove that check if you'd rather merge into existing folders.

# Directory Copy Script

Here's a Node.js script that recursively copies a directory and handles errors gracefully with friendly messages.

```javascript
#!/usr/bin/env node

const fs = require('fs').promises;
const path = require('path');

/**
 * Recursively copies a directory from `src` to `dest`.
 * Prints a friendly message if anything goes wrong.
 */
async function copyDirectory(src, dest) {
  try {
    // Sanity check: make sure the source exists and is a directory
    let stats;
    try {
      stats = await fs.stat(src);
    } catch (err) {
      if (err.code === 'ENOENT') {
        throw new Error(`Oops! I couldn't find the source folder: "${src}"`);
      }
      throw err;
    }

    if (!stats.isDirectory()) {
      throw new Error(`Hmm, "${src}" isn't a folder — it looks like a file.`);
    }

    // Prevent copying a directory into itself (which would loop forever)
    const srcResolved = path.resolve(src);
    const destResolved = path.resolve(dest);
    if (destResolved === srcResolved || destResolved.startsWith(srcResolved + path.sep)) {
      throw new Error(`I can't copy "${src}" into itself ("${dest}"). Try a different destination.`);
    }

    // Node's built-in recursive copy (Node >= 16.7)
    await fs.cp(src, dest, { recursive: true });

    console.log(`✅ All done! Copied "${src}" → "${dest}"`);
  } catch (err) {
    // Friendly, human-readable error messages
    let message = err.message;

    switch (err.code) {
      case 'EACCES':
        message = `I don't have permission to access "${err.path}". Try running with different permissions.`;
        break;
      case 'ENOSPC':
        message = `There's no space left on the disk. Free up some room and try again.`;
        break;
      case 'EEXIST':
        message = `The destination "${dest}" already exists and I can't overwrite it.`;
        break;
      case 'ENOTDIR':
        message = `Part of the path isn't a directory: "${err.path}".`;
        break;
      case 'EROFS':
        message = `The destination is on a read-only filesystem.`;
        break;
      case 'EMFILE':
      case 'ENFILE':
        message = `Too many files are open at once. Try closing some apps and retry.`;
        break;
    }

    console.error(`❌ Sorry, something went wrong while copying.`);
    console.error(`   ${message}`);
    process.exitCode = 1;
  }
}

// --- CLI entry point ---
const [src, dest] = process.argv.slice(2);

if (!src || !dest) {
  console.error('Usage: node copy-dir.js <source-folder> <destination-folder>');
  console.error('Example: node copy-dir.js ./my-project ./my-project-backup');
  process.exit(1);
}

copyDirectory(src, dest);
```

## Usage

```bash
node copy-dir.js ./source ./destination
```

## What it does

1. **Verifies the source** — checks it exists and is actually a directory.
2. **Guards against self-copy** — prevents copying a folder into itself (which would recurse forever).
3. **Uses `fs.cp` with `recursive: true`** — the modern, built-in way (Node ≥ 16.7). No extra dependencies.
4. **Maps common error codes** to friendly explanations (`EACCES`, `ENOSPC`, `EEXIST`, `EROFS`, etc.).
5. **Sets `process.exitCode = 1`** on failure so scripts/CI can detect the error, without throwing an unhandled rejection.

## Notes / variations

- **Older Node (< 16.7)?** Replace `fs.cp(...)` with a manual recursive walk using `fs.readdir` + `fs.copyFile` + `fs.mkdir`.
- **Want to overwrite the destination?** Add `{ recursive: true, force: true }` to the `fs.cp` options.
- **Want to preserve timestamps?** Add `preserveTimestamps: true`.
- **Want progress output?** Swap `fs.cp` for a manual walk and log each file as it's copied.

# Node.js Directory Copy Script

Here's a script that copies a directory recursively and handles errors gracefully with friendly messages:

```javascript
#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Recursively copies a directory from src to dest.
 * @param {string} src  - Source directory path
 * @param {string} dest - Destination directory path
 */
function copyDir(src, dest) {
  // Resolve absolute paths so error messages are clear
  const srcPath = path.resolve(src);
  const destPath = path.resolve(dest);

  // --- Friendly guard checks -------------------------------------------
  if (!fs.existsSync(srcPath)) {
    throw new FriendlyError(
      `I looked for "${srcPath}", but that folder doesn't exist.`,
      'Double-check the source path and try again.'
    );
  }

  if (!fs.statSync(srcPath).isDirectory()) {
    throw new FriendlyError(
      `"${srcPath}" is a file, not a folder.`,
      'This script only copies directories.'
    );
  }

  // Prevent copying a directory into itself
  const rel = path.relative(srcPath, destPath);
  if (rel && !rel.startsWith('..') && !path.isAbsolute(rel)) {
    throw new FriendlyError(
      `You're trying to copy "${srcPath}" into itself.`,
      'Choose a destination outside the source folder.'
    );
  }

  // --- Create destination and copy contents ----------------------------
  try {
    fs.mkdirSync(destPath, { recursive: true });
  } catch (err) {
    throw new FriendlyError(
      `I couldn't create the destination folder "${destPath}".`,
      describeFsError(err)
    );
  }

  const entries = fs.readdirSync(srcPath, { withFileTypes: true });

  for (const entry of entries) {
    const srcEntry = path.join(srcPath, entry.name);
    const destEntry = path.join(destPath, entry.name);

    try {
      if (entry.isDirectory()) {
        copyDir(srcEntry, destEntry);
      } else if (entry.isSymbolicLink()) {
        // Copy symlinks as symlinks instead of following them
        const link = fs.readlinkSync(srcEntry);
        fs.symlinkSync(link, destEntry);
      } else if (entry.isFile()) {
        fs.copyFileSync(srcEntry, destEntry);
      }
      // Sockets/FIFOs/etc. are silently skipped — rare in normal use
    } catch (err) {
      throw new FriendlyError(
        `Something went wrong while copying "${srcEntry}".`,
        describeFsError(err)
      );
    }
  }
}

/**
 * Turns common fs errors into human-friendly hints.
 */
function describeFsError(err) {
  switch (err.code) {
    case 'EACCES':
    case 'EPERM':
      return 'It looks like a permissions issue. Try running with elevated privileges.';
    case 'ENOSPC':
      return 'The disk appears to be full.';
    case 'ENOENT':
      return 'A file or folder disappeared during the copy.';
    case 'EEXIST':
      return 'A file already exists at the destination.';
    case 'EMFILE':
      return 'Too many files are open at once. Try closing some apps and retry.';
    default:
      return err.message;
  }
}

/**
 * Custom error so we can distinguish "expected" failures from bugs.
 */
class FriendlyError extends Error {
  constructor(message, hint) {
    super(message);
    this.name = 'FriendlyError';
    this.hint = hint;
  }
}

// --- CLI entry point ---------------------------------------------------
function main() {
  const [src, dest] = process.argv.slice(2);

  if (!src || !dest) {
    console.log('Usage: node copy-dir.js <source> <destination>');
    console.log('Example: node copy-dir.js ./photos ./backup/photos');
    process.exit(1);
  }

  console.log(`Copying "${src}" to "${dest}"...`);

  try {
    copyDir(src, dest);
    console.log('✅ All done! Your directory has been copied successfully.');
  } catch (err) {
    if (err instanceof FriendlyError) {
      console.error('\n❌ Sorry, I ran into a problem.');
      console.error(`   ${err.message}`);
      if (err.hint) console.error(`   💡 Hint: ${err.hint}`);
    } else {
      console.error('\n❌ Something unexpected happened:');
      console.error(`   ${err.message}`);
    }
    process.exit(1);
  }
}

main();
```

