### Simpler alternative (Node 16.7+)

If you don't need custom error messages, Node has this built in:

```javascript
const fs = require('fs/promises');
await fs.cp(src, dest, { recursive: true });
```

Here's an async Node.js implementation using `fs/promises`:

```js
const fs = require('fs/promises');

const DEFAULT_CONFIG = {
  port: 3000,
  host: 'localhost',
  debug: false,
};

/**
 * Reads a JSON config file, falling back to defaults if the file
 * is missing, unreadable, or contains invalid JSON.
 */
async function loadConfig(filePath, defaults = DEFAULT_CONFIG) {
  try {
    const raw = await fs.readFile(filePath, 'utf8');
    const parsed = JSON.parse(raw);

    // Merge so missing keys still get default values
    return { ...defaults, ...parsed };
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn(`Config not found at ${filePath} — using defaults.`);
    } else if (err instanceof SyntaxError) {
      console.warn(`Invalid JSON in ${filePath} — using defaults.`);
    } else {
      console.warn(`Could not read ${filePath}: ${err.message} — using defaults.`);
    }
    return { ...defaults };
  }
}

// Usage
loadConfig('./config.json').then((config) => {
  console.log(config);
});
```

**Notes:**
- `JSON.parse` throws a `SyntaxError` for malformed or empty files, so both cases are handled by the same branch.
- The spread merge (`{ ...defaults, ...parsed }`) means a partial config file still gets sensible values for keys it omits.
- If you want *only* the file's values (no merging), return `parsed` directly and `defaults` on error.

**Synchronous variant** if you need it:

```js
const fs = require('fs');

function loadConfigSync(filePath, defaults = DEFAULT_CONFIG) {
  try {
    return { ...defaults, ...JSON.parse(fs.readFileSync(filePath, 'utf8')) };
  } catch {
    return { ...defaults };
  }
}
```

For ESM, swap the import to `import fs from 'node:fs/promises';`.

Here's a robust Node.js implementation:

```javascript
const fs = require('fs/promises');
const path = require('path');

/**
 * Reads a JSON config file, falling back to defaults if the file
 * is missing, unreadable, or contains invalid JSON.
 *
 * @param {string} filePath - Path to the JSON config file
 * @param {object} defaults - Value to return when the file can't be used
 * @returns {Promise<object>} Parsed config, or a copy of the defaults
 */
async function readConfig(filePath, defaults = {}) {
  try {
    const contents = await fs.readFile(filePath, 'utf8');
    const parsed = JSON.parse(contents);

    // Guard against valid JSON that isn't an object (e.g. "null" or "[1,2]")
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      console.warn(`Config at ${filePath} is not a JSON object; using defaults.`);
      return { ...defaults };
    }

    return parsed;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn(`Config file not found at ${filePath}; using defaults.`);
    } else if (err instanceof SyntaxError) {
      console.warn(`Config file at ${filePath} contains invalid JSON; using defaults.`);
    } else {
      console.warn(`Could not read config at ${filePath}: ${err.message}; using defaults.`);
    }
    return { ...defaults };
  }
}

// Example usage
(async () => {
  const config = await readConfig(path.join(__dirname, 'config.json'), {
    port: 3000,
    debug: false,
  });
  console.log(config);
})();
```

**Key points:**

- **Missing file** → `ENOENT` is caught and defaults are returned.
- **Invalid JSON** → `JSON.parse` throws a `SyntaxError`, which is caught separately.
- **Valid JSON but wrong shape** (e.g. `null`, an array, or a number) → treated as invalid since a config should be an object.
- **Defaults are copied** (`{ ...defaults }`) so callers can't accidentally mutate the shared default object.

**Optional: merge defaults with partial config**

If a config file only contains some keys, you can merge it over the defaults:

```javascript
async function readConfigWithMerge(filePath, defaults = {}) {
  const config = await readConfig(filePath, {});
  return { ...defaults, ...config };
}
```

**ESM version** (if using `"type": "module"` in `package.json`):

```javascript
import { readFile } from 'fs/promises';
```

Here's a robust async implementation for Node.js (ESM):

```js
import { readFile } from 'node:fs/promises';

const isPlainObject = (v) =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

/** Deep clone that leaves functions/class instances by reference. */
function clone(value) {
  if (Array.isArray(value)) return value.map(clone);
  if (isPlainObject(value)) {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = clone(v);
    return out;
  }
  return value;
}

/** Recursively merge `override` onto `base` (arrays are replaced, not merged). */
function deepMerge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return override;
  const out = { ...base };
  for (const [key, value] of Object.entries(override)) {
    out[key] = key in base ? deepMerge(base[key], value) : value;
  }
  return out;
}

/**
 * Read a JSON config file, falling back to `defaults` if it is missing,
 * unreadable, malformed, or fails validation.
 *
 * @param {string} filePath
 * @param {object} [defaults]
 * @param {object} [options]
 * @param {(cfg: object) => true | string | string[]} [options.validate]
 *        Return `true` if valid, or an error message / list of messages.
 * @param {Console} [options.logger]
 * @returns {Promise<object>}
 */
export async function loadConfig(filePath, defaults = {}, options = {}) {
  const { validate, logger = console } = options;

  // 1. Read the file
  let raw;
  try {
    raw = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      logger.warn?.(`[config] "${filePath}" not found — using defaults.`);
    } else {
      logger.error?.(`[config] Could not read "${filePath}": ${err.message}`);
    }
    return clone(defaults);
  }

  // 2. Parse the JSON (strip a UTF-8 BOM, which breaks JSON.parse)
  let parsed;
  try {
    parsed = JSON.parse(raw.replace(/^\uFEFF/, ''));
  } catch (err) {
    logger.error?.(`[config] Invalid JSON in "${filePath}": ${err.message}`);
    return clone(defaults);
  }

  // 3. Require a top-level object
  if (!isPlainObject(parsed)) {
    logger.error?.(`[config] "${filePath}" must contain a JSON object.`);
    return clone(defaults);
  }

  // 4. Merge over the defaults
  const config = deepMerge(clone(defaults), parsed);

  // 5. Optional validation
  if (validate) {
    const result = validate(config);
    if (result !== true) {
      const msg = Array.isArray(result) ? result.join('; ') : result;
      logger.error?.(`[config] Validation failed for "${filePath}": ${msg}`);
      return clone(defaults);
    }
  }

  return config;
}
```

