### Behavior notes

| Situation | Result |
|---|---|
| File doesn't exist (`ENOENT`) | Defaults returned, warning logged |
| Permission error / directory read | Defaults returned, error logged |
| Malformed JSON or empty file | Defaults returned, parse error logged |
| Valid JSON but not an object (e.g. `[1,2]`) | Defaults returned |
| Valid JSON | Deep-merged over defaults |
| Validation fails | Defaults returned |

### Synchronous variant

If you need it in a script that can't `await`:

```js
import { readFileSync } from 'node:fs';

export function loadConfigSync(filePath, defaults = {}, { validate, logger = console } = {}) {
  let raw;
  try {
    raw = readFileSync(filePath, 'utf8');
  } catch (err) {
    logger.warn?.(`[config] "${filePath}" unreadable: ${err.message}`);
    return clone(defaults);
  }
  try {
    const parsed = JSON.parse(raw.replace(/^\uFEFF/, ''));
    if (!isPlainObject(parsed)) throw new Error('top-level value is not an object');
    const config = deepMerge(clone(defaults), parsed);
    if (validate) {
      const result = validate(config);
      if (result !== true) throw new Error(String(result));
    }
    return config;
  } catch (err) {
    logger.error?.(`[config] "${filePath}" invalid: ${err.message}`);
    return clone(defaults);
  }
}
```

Two design choices worth flagging: **arrays are replaced rather than merged** (so a file's `features: ["a"]` fully overrides the default list), and **defaults are deep-cloned on return** so callers can't accidentally mutate the shared `DEFAULTS` object across calls.

## Basic version (async, Node.js)

```js
import { readFile } from 'node:fs/promises';

/**
 * Reads a JSON config file, falling back to `defaults` when the file is
 * missing, unreadable, malformed, or fails validation.
 *
 * @param {string} filePath
 * @param {object} defaults
 * @param {(cfg: object) => boolean} [isValid] Optional validator.
 * @returns {Promise<object>}
 */
export async function loadConfig(filePath, defaults = {}, isValid) {
  let raw;

  try {
    raw = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'EISDIR' || err.code === 'EACCES') {
      console.warn(`[config] Could not read ${filePath} (${err.code}); using defaults.`);
      return { ...defaults };
    }
    throw err; // unexpected I/O failure — let it bubble up
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    console.warn(`[config] Invalid JSON in ${filePath}: ${err.message}; using defaults.`);
    return { ...defaults };
  }

  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    console.warn(`[config] ${filePath} does not contain a JSON object; using defaults.`);
    return { ...defaults };
  }

  if (typeof isValid === 'function' && !isValid(parsed)) {
    console.warn(`[config] ${filePath} failed validation; using defaults.`);
    return { ...defaults };
  }

  return { ...defaults, ...parsed };
}
```

## With deep merging of nested defaults

```js
function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

export function deepMerge(base, override) {
  const out = { ...base };
  for (const [key, value] of Object.entries(override ?? {})) {
    out[key] = isPlainObject(value) && isPlainObject(base?.[key])
      ? deepMerge(base[key], value)
      : value;
  }
  return out;
}
```

Then swap the final `return { ...defaults, ...parsed };` for `return deepMerge(defaults, parsed);`.

## Synchronous variant

```js
import { readFileSync } from 'node:fs';

export function loadConfigSync(filePath, defaults = {}, isValid) {
  let raw;
  try {
    raw = readFileSync(filePath, 'utf8');
  } catch {
    return { ...defaults };
  }

  try {
    const parsed = JSON.parse(raw);
    if (!isPlainObject(parsed)) return { ...defaults };
    if (isValid && !isValid(parsed)) return { ...defaults };
    return { ...defaults, ...parsed };
  } catch {
    return { ...defaults };
  }
}
