### Notes
- **Missing file** → `ENOENT` is caught and defaults are returned.
- **Invalid JSON** → `JSON.parse` throws `SyntaxError`, caught separately so a malformed file doesn't crash startup.
- **Wrong shape** → arrays/`null`/primitives are rejected even though they're valid JSON.
- **Validation** → pass a predicate (or plug in a schema lib like Zod/Ajv) for stricter checks.
- If you'd rather *fail loudly* on a corrupt file in production, rethrow the parse error instead of warning — the structure above makes that a one-line change.

## Async version (Node.js)

```js
import { readFile } from 'node:fs/promises';

const DEFAULT_CONFIG = {
  host: 'localhost',
  port: 8080,
  debug: false,
};

/**
 * Load a JSON config file, falling back to `defaults` when the file is
 * missing, unreadable, or not valid JSON.
 *
 * @param {string} path      Path to the JSON file.
 * @param {object} defaults  Values to use when the file can't be loaded.
 * @returns {Promise<{config: object, source: 'file'|'defaults', reason?: string}>}
 */
export async function loadConfig(path, defaults = DEFAULT_CONFIG) {
  let raw;

  try {
    raw = await readFile(path, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      return { config: { ...defaults }, source: 'defaults', reason: 'file not found' };
    }
    // EACCES, EISDIR, EIO, ... — these are real problems, not "use defaults".
    throw new Error(`Could not read config file "${path}": ${err.message}`, { cause: err });
  }

  // Strip a UTF-8 BOM; JSON.parse chokes on it.
  if (raw.charCodeAt(0) === 0xfeff) raw = raw.slice(1);

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    return { config: { ...defaults }, source: 'defaults', reason: `invalid JSON: ${err.message}` };
  }

  // A config file must contain a JSON *object*, not an array/primitive/null.
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { config: { ...defaults }, source: 'defaults', reason: 'top-level value is not an object' };
  }

  return { config: { ...defaults, ...parsed }, source: 'file' };
}
