 * Reads a JSON config file and falls back to defaults.
 *
 * @param {string} filePath  Path to the JSON file.
 * @param {object} defaults  Values returned when the file is missing or invalid.
 * @param {object} [options]
 * @param {boolean} [options.merge=false] Merge file values over the defaults
 *                                      (shallow) instead of replacing them.
 * @returns {Promise<object>} The parsed config, or the defaults.
 */
