  let raw;
  try {
    raw = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
      return { ...defaults }; // missing file
    }
    console.warn(`Could not read ${filePath}: ${err.message}`);
    return { ...defaults };
