const isPlainObject = (v) =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

/** Recursively merge `override` onto `base`. Arrays and scalars are replaced, not merged. */
export function deepMerge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return override === undefined ? base : override;
  }
  const out = { ...base };
  for (const [key, value] of Object.entries(override)) {
    out[key] = key in base ? deepMerge(base[key], value) : value;
  }
  return out;
}

const clone = (v) => (v === undefined ? v : structuredClone(v));

/**
 * Read a JSON config file, falling back to `defaults` when the file is
 * missing, empty, unreadable, malformed, or not a JSON object.
 *
 * @returns {Promise<{ config: object, source: 'file'|'defaults', error: Error|null }>}
 */
export async function loadConfig(filePath, defaults = {}, options = {}) {
  const { logger = console, merge = true } = options;

  let raw;
  try {
    raw = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
      logger.warn?.(`[config] ${filePath} not found — using defaults`);
    } else {
      logger.error?.(`[config] could not read ${filePath}: ${err.message}`);
    }
    return { config: clone(defaults), source: 'defaults', error: err };
  }

  // Strip UTF-8 BOM (common on Windows) and surrounding whitespace.
  const text = raw.replace(/^﻿/, '').trim();

  if (!text) {
    logger.warn?.(`[config] ${filePath} is empty — using defaults`);
    return { config: clone(defaults), source: 'defaults', error: null };
  }

  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (err) {
    logger.error?.(`[config] invalid JSON in ${filePath}: ${err.message}`);
    return { config: clone(defaults), source: 'defaults', error: err };
  }

  if (!isPlainObject(parsed)) {
    const err = new TypeError(
      `Config root must be a JSON object (got ${Array.isArray(parsed) ? 'array' : typeof parsed})`
    );
    logger.error?.(`[config] ${filePath}: ${err.message}`);
    return { config: clone(defaults), source: 'defaults', error: err };
  }

  return {
    config: merge ? deepMerge(defaults, parsed) : parsed,
    source: 'file',
    error: null,
  };
}

