    raw = fs.readFileSync(path.resolve(filePath), 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn(`[config] ${filePath} not found — using defaults`);
    } else {
      console.warn(`[config] Could not read ${filePath} (${err.code}) — using defaults`);
    }
    return { ...defaults };
  }

  try {
    const parsed = JSON.parse(raw);
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new SyntaxError('Config root must be a JSON object');
    }
    // Shallow merge so missing keys fall back to defaults
    return { ...defaults, ...parsed };
  } catch (err) {
    console.warn(`[config] Invalid JSON in ${filePath} (${err.message}) — using defaults`);
    return { ...defaults };
  }
}

module.exports = { loadConfig, DEFAULT_CONFIG };
