Here's a Node.js version using `fs/promises`:

```js
import { readFile } from 'node:fs/promises';

/**
 * Reads a JSON config file.
 * Returns `defaults` if the file is missing, empty, or contains invalid JSON.
 * Otherwise returns the parsed config, shallow-merged over the defaults.
 *
 * @param {string} filePath - Path to the JSON file
 * @param {object} [defaults={}] - Fallback values
 * @returns {Promise<object>}
 */
export async function readConfig(filePath, defaults = {}) {
  try {
    const raw = await readFile(filePath, 'utf8');
    const parsed = JSON.parse(raw);

    // A valid JSON file might still contain null, an array, or a scalar.
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return { ...defaults };
    }

    return { ...defaults, ...parsed };
  } catch (err) {
    // File doesn't exist, or isn't valid JSON -> fall back to defaults.
    if (err.code === 'ENOENT' || err instanceof SyntaxError) {
      return { ...defaults };
    }
    // Anything else (e.g. EACCES permission denied) is a real problem.
    throw err;
  }
}
```

**Usage:**

```js
const config = await readConfig('./config.json', {
  port: 3000,
  host: 'localhost',
});

console.log(config); // { port: 3000, host: 'localhost', ...file overrides }
```

**Notes:**

- `JSON.parse` throws a `SyntaxError` on malformed JSON or an empty file, so both cases are covered by the same catch branch.
- `ENOENT` covers a missing file (or a missing directory in the path).
- Other errors — like `EACCES` (permission denied) — are re-thrown, since silently substituting defaults would hide a genuine misconfiguration.
- The merge is shallow. If you need deep merging, use a library like `deepmerge` or write a recursive merge helper.

CommonJS equivalent — just swap the import for `const { readFile } = require('node:fs/promises');` and use `module.exports = readConfig;`.

Here's a robust Node.js implementation:

```js
const fs = require('node:fs/promises');
const path = require('node:path');

/**
 * Reads a JSON config file.
 * Returns `defaults` if the file is missing, unreadable, or contains invalid JSON.
 *
 * @param {string} filePath - Path to the JSON config file
 * @param {object} defaults - Value to return when the config can't be loaded
 * @returns {Promise<object>} The parsed config, or the defaults
 */
async function readJsonConfig(filePath, defaults = {}) {
  try {
    const raw = await fs.readFile(filePath, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    // Missing file, permission problem, directory instead of file, etc.
    if (err.code === 'ENOENT' || err.code === 'EISDIR' || err.code === 'EACCES') {
      console.warn(`Config not found at ${filePath}; using defaults.`);
      return defaults;
    }

    // Malformed JSON (SyntaxError from JSON.parse)
    if (err instanceof SyntaxError) {
      console.warn(`Invalid JSON in ${filePath}; using defaults.`);
      return defaults;
    }

    throw err; // Unexpected error — let the caller decide
  }
}
```

