- **Security:** `JSON.parse` is safe against code execution, but be careful with `__proto__` keys in untrusted configs — use `JSON.parse(raw, (k, v) => (k === '__proto__' ? undefined : v))` if configs come from untrusted sources.

## Async version (Node.js)

```js
import { readFile } from 'node:fs/promises';

const DEFAULT_CONFIG = {
  host: 'localhost',
  port: 8080,
  debug: false,
};

/**
 * Reads a JSON config file.
 * Falls back to `defaults` if the file is missing, unreadable-as-JSON,
 * or fails an optional `validate` check.
 *
 * @param {string} filePath
 * @param {object} defaults
 * @param {(cfg: object) => boolean} [validate] - return false to reject the config
 * @returns {Promise<object>}
 */
export async function loadConfig(filePath, defaults = DEFAULT_CONFIG, validate) {
  let raw;

  // 1. Read the file — handle "missing"
  try {
    raw = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
      console.warn(`[config] "${filePath}" not found — using defaults.`);
      return { ...defaults };
    }
    // Real I/O problems (permissions, etc.) should probably surface
    throw err;
  }

  // 2. Parse — handle "invalid"
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    console.warn(`[config] "${filePath}" is not valid JSON — using defaults.`);
    return { ...defaults };
  }

  // 3. Sanity-check the shape (must be a plain object)
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    console.warn(`[config] "${filePath}" must contain a JSON object — using defaults.`);
    return { ...defaults };
  }

  // 4. Optional semantic validation
  if (typeof validate === 'function' && !validate(parsed)) {
    console.warn(`[config] "${filePath}" failed validation — using defaults.`);
    return { ...defaults };
  }

  // 5. Merge so any keys absent from the file still get default values
  return { ...defaults, ...parsed };
}
```

