**Notes**
- The returned object is a shallow copy, so mutating it won't affect the defaults.
- Only `ENOENT`/`ENOTDIR` are swallowed by default; other errors (e.g. `EACCES`) are re-thrown since they usually indicate a real problem rather than "no config yet".
- Shallow merge means nested objects are replaced wholesale. For deep merging, use something like `structuredClone` + a recursive merge, or a library like `lodash.merge`.

## Basic version (Node.js, ESM)

```js
import { readFile } from 'node:fs/promises';

const isPlainObject = (v) =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

/**
 * Read a JSON config file, falling back to `defaults` if the file is
 * missing, unreadable, empty, or not valid JSON.
 *
 * @param {string} filePath
 * @param {object} [defaults={}]
 * @param {{ merge?: boolean, throwOnError?: boolean }} [options]
 * @returns {Promise<object>}
 */
export async function loadConfig(filePath, defaults = {}, options = {}) {
  const { merge = false, throwOnError = false } = options;

  let raw;
  try {
    raw = await readFile(filePath, 'utf8');
  } catch (err) {
    // Missing file (or a path component isn't a directory) -> use defaults.
    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
      return structuredClone(defaults);
    }
    // EACCES, EISDIR, EMFILE, ... are real problems: surface them.
    if (throwOnError) throw err;
    console.warn(`[config] Could not read ${filePath}: ${err.message}`);
    return structuredClone(defaults);
  }

  // Strip UTF-8 BOM, which JSON.parse chokes on.
  const text = raw.replace(/^\uFEFF/, '').trim();

  if (!text) return structuredClone(defaults); // empty file

  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (err) {
    if (throwOnError) throw new Error(`Invalid JSON in ${filePath}: ${err.message}`);
    console.warn(`[config] Invalid JSON in ${filePath}: ${err.message}`);
    return structuredClone(defaults);
  }

  // A config must be a JSON object; arrays/primitives are treated as invalid.
  if (!isPlainObject(parsed)) {
    if (throwOnError) throw new Error(`${filePath} must contain a JSON object`);
    console.warn(`[config] ${filePath} must contain a JSON object; using defaults`);
    return structuredClone(defaults);
  }

  return merge ? deepMerge(defaults, parsed) : { ...defaults, ...parsed };
}
```

### Deep merge helper

```js
function deepMerge(base, override) {
  const out = { ...base };
  for (const [key, value] of Object.entries(override)) {
    // Guard against prototype pollution via "__proto__" / "constructor".
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;

    out[key] =
      isPlainObject(value) && isPlainObject(base?.[key])
        ? deepMerge(base[key], value)
        : value;
  }
  return out;
}
```

