## More robust version

Adds a timeout, generic typing, and runtime shape validation so a malformed payload doesn't slip through as a valid profile.

```ts
interface UserProfile {
  id: string;
  name: string;
  email: string;
}

function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.name === "string" &&
    typeof v.email === "string"
  );
}

export async function fetchUserProfile(
  userId: string,
  { timeoutMs = 5000, signal }: { timeoutMs?: number; signal?: AbortSignal } = {},
): Promise<UserProfile | null> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  // Chain the caller's signal so both can cancel the request.
  const onAbort = () => controller.abort();
  signal?.addEventListener("abort", onAbort);

  try {
    const response = await fetch(`/api/users/${encodeURIComponent(userId)}`, {
      signal: controller.signal,
      headers: { Accept: "application/json" },
    });

    if (!response.ok) {
      console.error(`Failed to fetch user ${userId}: ${response.status} ${response.statusText}`);
      return null;
    }

    const data: unknown = await response.json();

    if (!isUserProfile(data)) {
      console.error(`Unexpected payload shape for user ${userId}`);
      return null;
    }

    return data;
  } catch (error) {
    if (error instanceof DOMException && error.name === "AbortError") {
      console.error(`Request for user ${userId} timed out after ${timeoutMs}ms`);
    } else {
      console.error(`Network error fetching user ${userId}:`, error);
    }
    return null;
  } finally {
    clearTimeout(timer);
    signal?.removeEventListener("abort", onAbort);
  }
}
```

### Notes

- **`response.ok` check matters** — `fetch` only rejects on network-level failures, not on `404`/`500`. Without this check, an error page's JSON would be returned as if it were a profile.
- **`encodeURIComponent(userId)`** prevents a malicious or malformed ID from altering the request path.
- **Timeout via `AbortController`** avoids hanging forever on a stalled connection. If your runtime supports `AbortSignal.timeout(ms)`, that simplifies the code considerably.
- **Runtime validation** is worth it whenever the response comes from outside your control — the `as UserProfile` cast in the basic version is a compile-time promise the server may not keep.

### If you'd rather throw than return null

Returning `null` conflates "user doesn't exist" with "network is down." If the caller needs to tell those apart, throw a typed error instead:

```ts
export class UserFetchError extends Error {
  constructor(
    message: string,
    readonly status?: number,
    readonly cause?: unknown,
  ) {
    super(message);
    this.name = "UserFetchError";
  }
}

export async function fetchUserProfileOrThrow(userId: string): Promise<UserProfile> {
  const response = await fetch(`/api/users/${encodeURIComponent(userId)}`);

  if (response.status === 404) throw new UserFetchError("User not found", 404);
  if (!response.ok) throw new UserFetchError(`Request failed: ${response.status}`, response.status);

  return (await response.json()) as UserProfile;
}
```

Callers can then use `try/catch` and inspect `error.status` to distinguish a missing user from a transient failure.

