export interface UserProfile {
  id: string;
  username: string;
  email: string;
  displayName: string;
  avatarUrl?: string;
  createdAt: string;
}

export interface FetchUserOptions {
  /** Caller-supplied signal, e.g. to cancel when a component unmounts. */
  signal?: AbortSignal;
  /** Abort the request after this many ms. Set to 0 to disable. */
  timeoutMs?: number;
  /** Base URL of the API. */
  baseUrl?: string;
}

/**
 * Fetches a user profile.
 * @returns the profile, or `null` if the request fails for any reason
 *          (network error, timeout, non-2xx status, malformed body).
 */
export async function fetchUserProfile(
  userId: string,
  options: FetchUserOptions = {},
): Promise<UserProfile | null> {
  const { signal, timeoutMs = 10_000, baseUrl = "https://api.example.com" } = options;

  // Combine the caller's signal with our own timeout signal.
  const controller = new AbortController();
  const timer =
    timeoutMs > 0
      ? setTimeout(() => controller.abort(new DOMException("Timeout", "TimeoutError")), timeoutMs)
      : undefined;

  const forwardAbort = () => controller.abort(signal?.reason);
  if (signal) {
    if (signal.aborted) controller.abort(signal.reason);
    else signal.addEventListener("abort", forwardAbort, { once: true });
  }

  try {
    const response = await fetch(
      `${baseUrl}/users/${encodeURIComponent(userId)}`,
      {
        signal: controller.signal,
        headers: { Accept: "application/json" },
      },
    );

    // 404 (no such user) and 5xx (server error) both mean "no profile".
    if (!response.ok) return null;

    const data: unknown = await response.json();
    return isUserProfile(data) ? data : null;
  } catch {
    // Network failure, abort/timeout, or invalid JSON.
    return null;
  } finally {
    if (timer !== undefined) clearTimeout(timer);
    signal?.removeEventListener("abort", forwardAbort);
  }
}

/** Runtime guard so a malformed payload can't leak through as a UserProfile. */
function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  const p = value as Record<string, unknown>;
  return (
    typeof p.id === "string" &&
    typeof p.username === "string" &&
    typeof p.email === "string" &&
    typeof p.displayName === "string" &&
    typeof p.createdAt === "string" &&
    (p.avatarUrl === undefined || typeof p.avatarUrl === "string")
  );
}
