```ts
export interface UserProfile {
  id: string;
  username: string;
  email: string;
  displayName: string | null;
  avatarUrl: string | null;
  createdAt: string;
}

export interface FetchOptions {
  /** Abort from the outside (e.g. component unmount). */
  signal?: AbortSignal;
  /** Give up after this many ms. Default: 10_000. */
  timeoutMs?: number;
  /** Extra headers, e.g. an auth token. */
  headers?: Record<string, string>;
}

/**
 * Fetches JSON from `url` and returns it, or `null` if anything goes wrong:
 * network error, timeout, non-2xx status, malformed JSON, or a payload that
 * doesn't match the expected shape.
 */
export async function fetchJsonOrNull<T>(
  url: string,
  isValid: (value: unknown) => value is T,
  options: FetchOptions = {},
): Promise<T | null> {
  const { signal, timeoutMs = 10_000, headers = {} } = options;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  // Forward an externally supplied abort signal into our controller.
  const forwardAbort = () => controller.abort();
  if (signal?.aborted) forwardAbort();
  else signal?.addEventListener("abort", forwardAbort, { once: true });

  try {
    const response = await fetch(url, {
      method: "GET",
      headers: { Accept: "application/json", ...headers },
      signal: controller.signal,
    });

    // fetch() does NOT reject on 4xx/5xx — it resolves normally.
    if (!response.ok) {
      console.warn(`fetchJsonOrNull: HTTP ${response.status} ${response.statusText} for ${url}`);
      return null;
    }

    const data: unknown = await response.json();
    return isValid(data) ? data : null;
  } catch (error) {
    // Network failure, abort/timeout, or invalid JSON.
    if ((error as Error)?.name !== "AbortError") {
      console.warn(`fetchJsonOrNull failed for ${url}:`, error);
    }
    return null;
  } finally {
    clearTimeout(timer);
    signal?.removeEventListener("abort", forwardAbort);
  }
}

function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  const p = value as Record<string, unknown>;
  return (
    typeof p.id === "string" &&
    typeof p.username === "string" &&
    typeof p.email === "string" &&
    (p.displayName === null || typeof p.displayName === "string") &&
    (p.avatarUrl === null || typeof p.avatarUrl === "string") &&
    typeof p.createdAt === "string"
  );
}

export function fetchUserProfile(
  userId: string,
  options: FetchOptions = {},
): Promise<UserProfile | null> {
  const url = `/api/users/${encodeURIComponent(userId)}`;
  return fetchJsonOrNull(url, isUserProfile, options);
}
