Here's a robust implementation that handles network errors, non-2xx responses, invalid JSON, and timeouts:

```ts
interface UserProfile {
  id: string;
  username: string;
  email: string;
  createdAt: string;
}

interface FetchOptions {
  /** Abort the request after this many milliseconds. Default: 10_000 */
  timeoutMs?: number;
  /** Extra headers merged into the request. */
  headers?: Record<string, string>;
  /** Optional bearer token. */
  token?: string;
}

async function fetchUserProfile(
  userId: string,
  options: FetchOptions = {},
): Promise<UserProfile | null> {
  const { timeoutMs = 10_000, headers = {}, token } = options;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(`/api/users/${encodeURIComponent(userId)}`, {
      signal: controller.signal,
      headers: {
        Accept: "application/json",
        ...headers,
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
    });

    // 404 is a legitimate "no such user" answer, not a crash.
    if (response.status === 404) return null;

    if (!response.ok) {
      throw new Error(`Request failed with status ${response.status}`);
    }

    const data: unknown = await response.json();
    return parseUserProfile(data);
  } catch (error) {
    // Network failure, abort/timeout, malformed JSON, or a bad status.
    console.warn("Failed to fetch user profile:", error);
    return null;
  } finally {
    clearTimeout(timer);
  }
}

// Treat unexpected shapes as failures rather than letting bad data escape.
function parseUserProfile(data: unknown): UserProfile | null {
  if (typeof data !== "object" || data === null) return null;

  const candidate = data as Partial<UserProfile>;
  if (
    typeof candidate.id !== "string" ||
    typeof candidate.username !== "string" ||
    typeof candidate.email !== "string" ||
    typeof candidate.createdAt !== "string"
  ) {
    return null;
  }

  return candidate as UserProfile;
}
```

