```ts
export interface UserProfile {
  id: string;
  username: string;
  email: string;
  displayName?: string;
  avatarUrl?: string;
  createdAt: string;
}

export interface FetchUserOptions {
  /** Caller-supplied signal for cancellation. */
  signal?: AbortSignal;
  /** Abort the request after this many ms. Defaults to 10_000. */
  timeoutMs?: number;
  /** Extra headers, e.g. an Authorization token. */
  headers?: Record<string, string>;
}

export async function fetchUserProfile(
  userId: string,
  options: FetchUserOptions = {},
): Promise<UserProfile | null> {
  const { signal, timeoutMs = 10_000, headers } = options;

  const controller = new AbortController();
  const timer =
    timeoutMs > 0
      ? setTimeout(() => controller.abort(new Error(`Request timed out after ${timeoutMs}ms`)), timeoutMs)
      : undefined;

  // Combine the caller's signal with our timeout signal.
  const combinedSignal = signal
    ? AbortSignal.any([signal, controller.signal])
    : controller.signal;

  try {
    const response = await fetch(`/api/users/${encodeURIComponent(userId)}`, {
      method: "GET",
      headers: { Accept: "application/json", ...headers },
      signal: combinedSignal,
    });

    // Non-2xx statuses are failures too.
    if (!response.ok) {
      console.warn(`fetchUserProfile: HTTP ${response.status} for user ${userId}`);
      return null;
    }

    const profile = (await response.json()) as UserProfile;

    // Guard against a 200 response with an unexpected shape.
    if (!profile || typeof profile.id !== "string") {
      console.warn(`fetchUserProfile: malformed payload for user ${userId}`);
      return null;
    }

    return profile;
  } catch (error) {
    // Network failure, abort, or a JSON parse error.
    console.warn(`fetchUserProfile: request failed for user ${userId}`, error);
    return null;
  } finally {
    clearTimeout(timer);
  }
}
