    | { ok: true; value: T }
    | { ok: false; reason: "not-found" | "http" | "network" | "timeout" | "parse" };

  export async function fetchUserProfileResult(
    userId: string,
  ): Promise<Result<UserProfile>> { /* ... */ }
  ```

- **Runtime validation** — the `as UserProfile` cast is compile-time only. If the API is untrusted, validate with a schema (Zod, Valibot) or hand-rolled type guards before using the data.
- **Retry logic** belongs outside this function (e.g. a wrapper with exponential backoff), since it needs to distinguish transient errors from permanent ones.

Here's a production-ready version. It handles the three ways a request can "fail": network errors, HTTP error statuses (4xx/5xx), and malformed JSON.

```ts
// ---------- Types ----------

export interface UserProfile {
  id: string;
  username: string;
  email: string;
  displayName: string | null;
  avatarUrl: string | null;
  createdAt: string;
}

export interface FetchUserOptions {
  /** Caller-supplied cancellation signal. */
  signal?: AbortSignal;
  /** Abort the request after this many ms. Set to 0 to disable. */
  timeoutMs?: number;
  /** Extra headers to merge in. */
  headers?: Record<string, string>;
  /** Bearer token, if the API requires auth. */
  token?: string;
}

const API_BASE_URL = "https://api.example.com";

// ---------- Runtime validation (optional but recommended) ----------

function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  const p = value as Record<string, unknown>;
  return typeof p.id === "string" && typeof p.username === "string";
}

// ---------- The function ----------

export async function getUserProfile(
  userId: string,
  options: FetchUserOptions = {},
): Promise<UserProfile | null> {
  const { signal, timeoutMs = 10_000, headers = {}, token } = options;

  // Combine the caller's signal with our own timeout signal.
  const controller = new AbortController();
  let timedOut = false;

  const timer =
    timeoutMs > 0
      ? setTimeout(() => {
          timedOut = true;
          controller.abort();
        }, timeoutMs)
      : undefined;

  const forwardAbort = () => controller.abort();
  if (signal?.aborted) {
    controller.abort();
  } else {
    signal?.addEventListener("abort", forwardAbort, { once: true });
  }

  try {
    const response = await fetch(
      `${API_BASE_URL}/users/${encodeURIComponent(userId)}`,
      {
        method: "GET",
        headers: {
          Accept: "application/json",
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
          ...headers,
        },
        signal: controller.signal,
      },
    );

    // HTTP-level failure: 404, 500, etc. `fetch` does NOT reject here.
    if (!response.ok) {
      console.warn(
        `[getUserProfile] ${userId} failed: ${response.status} ${response.statusText}`,
      );
      return null;
    }

    const data: unknown = await response.json();

    if (!isUserProfile(data)) {
      console.warn(`[getUserProfile] ${userId} returned an unexpected shape`);
      return null;
    }

    return data;
  } catch (error) {
    // Network error, DNS failure, CORS block, timeout, or aborted request.
    const reason = timedOut ? `timed out after ${timeoutMs}ms` : String(error);
    console.warn(`[getUserProfile] ${userId} request failed: ${reason}`);
    return null;
  } finally {
    if (timer !== undefined) clearTimeout(timer);
    signal?.removeEventListener("abort", forwardAbort);
  }
}
```

