Here's a script that copies a directory recursively and gives friendly, actionable messages when something goes wrong.

```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');

/**
 * Copy a directory (recursively) from `src` to `dest`.
 *
 * @param {string} src  Source directory path.
 * @param {string} dest Destination directory path.
 */
async function copyDirectory(src, dest) {
  const source = path.resolve(src);
  const destination = path.resolve(dest);

  // --- Pre-flight checks so we can give nicer messages than raw errno text ---
  let sourceStats;
  try {
    sourceStats = await fs.stat(source);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`The source folder "${source}" doesn't exist. Please check the path and try again.`);
    }
    if (err.code === 'EACCES') {
      throw new Error(`You don't have permission to read "${source}". Try running with elevated permissions.`);
    }
    throw err;
  }

  if (!sourceStats.isDirectory()) {
    throw new Error(`"${source}" is a file, not a folder. This script only copies directories.`);
  }

  // Guard against copying a folder into itself (e.g. cp -r a a/b), which would recurse forever.
  if (destination === source || destination.startsWith(source + path.sep)) {
    throw new Error(`Can't copy "${source}" into itself. Please choose a different destination.`);
  }

  // --- Do the copy ---
  await fs.cp(source, destination, {
    recursive: true,
    force: true,        // overwrite existing files
    errorOnExist: false,
    preserveTimestamps: true,
  });

  return destination;
}

// --- CLI entry point ---
async function main() {
  const [src, dest] = process.argv.slice(2);

  if (!src || !dest) {
    console.log('Usage: node copy-dir.js <source-folder> <destination-folder>');
    console.log('Example: node copy-dir.js ./photos ./photos-backup');
    process.exitCode = 1;
    return;
  }

  try {
    const result = await copyDirectory(src, dest);
    console.log(`✅ Done! Copied "${src}" to "${result}".`);
  } catch (err) {
    console.error(`❌ Oops — the copy didn't work: ${err.message}`);
    process.exitCode = 1;
  }
}

if (require.main === module) {
  main();
}

module.exports = { copyDirectory };
```

**Usage:**

```bash
node copy-dir.js ./photos ./photos-backup
```

**Notes:**

- Requires **Node.js 16.7+** for `fs.promises.cp`. On older versions, swap the copy step for a manual `fs.readdir`/`fs.copyFile` recursion.
- `force: true` overwrites existing files at the destination; remove it if you'd rather fail on conflicts.
- The "copy into itself" check prevents the classic infinite-recursion footgun.
- The `copyDirectory` function is exported, so you can `require()` it and use it in your own code with `try/catch` instead of the CLI wrapper.

