## `copy-dir.js`

```js
#!/usr/bin/env node
'use strict';

const fs = require('fs/promises');
const path = require('path');

/**
 * Recursively copies a directory (or a single file) to a destination.
 * Uses fs.cp, available in Node.js 16.7+.
 */
async function copyDir(src, dest) {
  await fs.cp(src, dest, {
    recursive: true,
    force: true,        // overwrite existing files
    errorOnExist: false // don't throw if destination already exists
  });
}

async function main() {
  const src = process.argv[2];
  const dest = process.argv[3];

  if (!src || !dest) {
    console.log('Usage: node copy-dir.js <source-dir> <destination-dir>');
    process.exitCode = 1;
    return;
  }

  try {
    // Make sure the source actually exists before we start.
    const stats = await fs.stat(src);
    if (!stats.isDirectory() && !stats.isFile()) {
      throw new Error(`"${src}" is not a regular file or directory.`);
    }

    // Ensure the parent folder of the destination exists.
    await fs.mkdir(path.dirname(path.resolve(dest)), { recursive: true });

    await copyDir(src, dest);
    console.log(`✅ Done! Copied "${src}" to "${dest}".`);
  } catch (err) {
    console.error(`❌ Oops! Something went wrong while copying: ${err.message}`);
    process.exitCode = 1;
  }
}

main();
```

