```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');

// ---------------------------------------------------------------------------
// Usage: node copy-dir.js <source-dir> <destination-dir>
// ---------------------------------------------------------------------------

const [, , sourceArg, destArg] = process.argv;

if (!sourceArg || !destArg) {
  console.error('Usage: node copy-dir.js <source-dir> <destination-dir>');
  process.exit(1);
}

const source = path.resolve(sourceArg);
const destination = path.resolve(destArg);

/**
 * Turn a low-level system error into something a human can act on.
 */
function friendlyError(err) {
  switch (err.code) {
    case 'ENOENT':
      return `The source folder doesn't exist:\n  ${source}`;
    case 'EACCES':
    case 'EPERM':
      return `Permission denied while copying. Try running with elevated permissions (e.g. sudo).`;
    case 'ENOSPC':
      return `Out of disk space — the copy couldn't be completed.`;
    case 'EEXIST':
      return `The destination already exists:\n  ${destination}`;
    case 'EXDEV':
      return `Source and destination are on different filesystems, which can't be copied directly.`;
    case 'ENOTDIR':
      return `One of the paths is a file, not a directory.`;
    case 'EBUSY':
      return `The destination is in use by another program. Close it and try again.`;
    default:
      return `Unexpected error: ${err.message}`;
  }
}

async function main() {
  // Sanity-check the source before we start copying.
  let stats;
  try {
    stats = await fs.stat(source);
  } catch (err) {
    console.error(`❌ ${friendlyError(err)}`);
    process.exit(1);
  }

  if (!stats.isDirectory()) {
    console.error(`❌ The source is not a directory:\n  ${source}`);
    process.exit(1);
  }

  try {
    await fs.cp(source, destination, {
      recursive: true,
      force: true,        // overwrite existing files
      errorOnExist: false,
      preserveTimestamps: true,
    });

    console.log(`✅ Copied "${source}" → "${destination}"`);
  } catch (err) {
    console.error(`❌ ${friendlyError(err)}`);
    process.exit(1);
  }
}

main();
