```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const sourceArg = process.argv[2];
const destinationArg = process.argv[3];

// Turn a low-level error into something a human can act on.
function friendlyError(err) {
  switch (err.code) {
    case 'ENOENT':
      return `We couldn't find "${err.path || sourceArg}". Please double-check the path.`;
    case 'EACCES':
    case 'EPERM':
      return `Permission denied while accessing "${err.path || 'the requested path'}". Try running with elevated permissions.`;
    case 'ENOTDIR':
      return `"${err.path || sourceArg}" isn't a folder, so it can't be copied as one.`;
    case 'EEXIST':
      return `The destination "${destinationArg}" already exists and can't be overwritten.`;
    case 'ENOSPC':
      return `There's not enough space on the disk to finish the copy.`;
    case 'EBUSY':
      return `The destination is busy — a file may be open in another program. Close it and try again.`;
    case 'ERR_FS_CP_EINVAL':
      return `The destination can't live inside the source folder. Please pick a different destination.`;
    default:
      return `Something went wrong while copying: ${err.message}`;
  }
}

function fail(message) {
  console.error(`❌ ${message}`);
  process.exit(1);
}

async function main() {
  if (!sourceArg || !destinationArg) {
    console.log('Usage: node copy-dir.js <source-directory> <destination-directory>');
    process.exit(1);
  }

  const source = path.resolve(sourceArg);
  const destination = path.resolve(destinationArg);

  // 1. Make sure the source exists and really is a directory.
  let stats;
  try {
    stats = await fs.promises.stat(source);
  } catch (err) {
    fail(friendlyError(err));
  }

  if (!stats.isDirectory()) {
    fail(`"${sourceArg}" isn't a folder. This script only copies directories.`);
  }

  // 2. Guard against copying a folder into itself (infinite recursion).
  if (destination === source || destination.startsWith(source + path.sep)) {
    fail('The destination cannot be inside the source folder. Please choose a different destination.');
  }

  // 3. Do the copy.
  try {
    await fs.promises.cp(source, destination, {
      recursive: true,        // include subfolders and their contents
      force: true,            // overwrite existing files
      preserveTimestamps: true // keep original modification times
    });
  } catch (err) {
    fail(friendlyError(err));
  }

  console.log(`✅ Done! Copied "${sourceArg}" → "${destinationArg}".`);
}

main().catch((err) => fail(friendlyError(err)));
