## `copy-dir.js`

```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const fsp = require('node:fs/promises');
const path = require('node:path');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Turn a low-level fs error into something a human can actually act on. */
function friendlyError(err, src, dest) {
  switch (err.code) {
    case 'ENOENT':
      return `I couldn't find "${err.path || src}". Does it exist?`;

    case 'EACCES':
    case 'EPERM':
      return `Permission denied while copying to "${dest}". Try again with elevated permissions (e.g. sudo).`;

    case 'ENOTEMPTY':
    case 'EEXIST':
      return `"${dest}" already exists and isn't empty. Re-run with --force to overwrite existing files.`;

    case 'EXDEV':
      return `Can't copy between different filesystems directly. Try using "cp -r" instead.`;

    case 'ENOSPC':
      return `There's not enough space left on the disk to finish the copy.`;

    case 'ERR_FS_CP_EINVAL':
      return `The copy was interrupted or the paths are invalid.`;

    default:
      return `Something went wrong while copying "${src}" to "${dest}": ${err.message}`;
  }
}

function usage() {
  return `
Usage: node copy-dir.js <source> <destination> [options]

Options:
  --force        Overwrite existing files in the destination (default: true)
  --no-force     Keep existing files, skip anything that already exists
  --dry-run      Show what would be copied without touching the disk
  -h, --help     Show this help message
`.trim();
}

/** Parse argv into { src, dest, force, dryRun }. */
function parseArgs(argv) {
  const opts = { src: null, dest: null, force: true, dryRun: false };

  for (const arg of argv) {
    if (arg === '-h' || arg === '--help') {
      console.log(usage());
      process.exit(0);
    } else if (arg === '--force') {
      opts.force = true;
    } else if (arg === '--no-force') {
      opts.force = false;
    } else if (arg === '--dry-run') {
      opts.dryRun = true;
    } else if (arg.startsWith('-')) {
      throw Object.assign(new Error(`Unknown option "${arg}".`), { code: 'EBADOPT' });
    } else if (opts.src === null) {
      opts.src = arg;
    } else if (opts.dest === null) {
      opts.dest = arg;
    } else {
      throw Object.assign(new Error('Too many arguments.'), { code: 'EBADOPT' });
    }
  }

  if (!opts.src || !opts.dest) {
    throw Object.assign(new Error('Please provide both a source and a destination.'), {
      code: 'EBADOPT',
    });
  }

  opts.src = path.resolve(opts.src);
  opts.dest = path.resolve(opts.dest);
  return opts;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  let opts;
  try {
    opts = parseArgs(process.argv.slice(2));
  } catch (err) {
    console.error(`❌ ${err.message}\n`);
    console.error(usage());
    process.exitCode = 1;
    return;
  }

  const { src, dest, force, dryRun } = opts;

  // --- Pre-flight checks ---------------------------------------------------
  let srcStat;
  try {
    srcStat = await fsp.stat(src);
  } catch (err) {
    console.error(`❌ ${friendlyError(err, src, dest)}`);
    process.exitCode = 1;
    return;
  }

  if (!srcStat.isDirectory()) {
    console.error(`❌ "${src}" isn't a directory — this script only copies folders.`);
    process.exitCode = 1;
    return;
  }

  if (src === dest) {
    console.error(`❌ Source and destination are the same folder ("${src}").`);
    process.exitCode = 1;
    return;
  }

  if (dest.startsWith(src + path.sep)) {
    console.error(`❌ Can't copy a folder into itself ("${dest}" is inside "${src}").`);
    process.exitCode = 1;
    return;
  }

  try {
    const destStat = await fsp.stat(dest);
    if (!destStat.isDirectory()) {
      console.error(`❌ "${dest}" already exists and is a file. Please choose a different destination.`);
      process.exitCode = 1;
      return;
    }
  } catch (err) {
    if (err.code !== 'ENOENT') {
      console.error(`❌ ${friendlyError(err, src, dest)}`);
      process.exitCode = 1;
      return;
    }
    // Destination doesn't exist yet — that's fine, we'll create it.
  }

  // --- Copy ----------------------------------------------------------------
  let fileCount = 0;
  let dirCount = 0;

  try {
    await fsp.cp(src, dest, {
      recursive: true,
      force,
      errorOnExist: !force,
      preserveTimestamps: true,
      filter: (from) => {
        // Skip noisy/system folders and count what we're moving.
        const base = path.basename(from);
        if (from !== src && (base === 'node_modules' || base === '.git')) {
          return false;
        }
        return true;
      },
    });

    // Count results for a nicer summary.
    const walk = async (dir) => {
      const entries = await fsp.readdir(dir, { withFileTypes: true });
      for (const entry of entries) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          dirCount++;
          await walk(full);
        } else {
          fileCount++;
        }
      }
    };
    await walk(dest);
  } catch (err) {
    console.error(`❌ ${friendlyError(err, src, dest)}`);
    process.exitCode = 1;
    return;
  }

  if (dryRun) {
    console.log(`✅ Dry run finished — "${src}" looks copyable to "${dest}".`);
  } else {
    console.log(
      `✅ Copied "${src}" → "${dest}" (${fileCount} file${fileCount === 1 ? '' : 's'}, ` +
        `${dirCount} folder${dirCount === 1 ? '' : 's'}).`
    );
  }
}

main().catch((err) => {
  // Last-resort safety net so we never dump a raw stack trace at the user.
  console.error(`❌ Unexpected problem: ${err && err.message ? err.message : err}`);
  process.exitCode = 1;
});
```

