```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');

async function main() {
  const [srcArg, destArg] = process.argv.slice(2);

  // 1. Validate arguments
  if (!srcArg || !destArg) {
    console.error('Usage: node copy-dir.js <source-directory> <destination-directory>');
    process.exitCode = 1;
    return;
  }

  const source = path.resolve(srcArg);
  const destination = path.resolve(destArg);

  try {
    // 2. Make sure the source actually exists and is a directory
    const stats = await fs.stat(source);
    if (!stats.isDirectory()) {
      console.error(`Oops! "${srcArg}" is not a directory, so there is nothing to copy.`);
      process.exitCode = 1;
      return;
    }

    // 3. Copy the directory recursively (Node.js 16.7+)
    await fs.cp(source, destination, {
      recursive: true,
      force: true,      // overwrite existing files
      errorOnExist: false
    });

    console.log(`✅ Done! Copied "${srcArg}" to "${destArg}".`);
  } catch (err) {
    // 4. Turn common error codes into friendly messages
    switch (err.code) {
      case 'ENOENT':
        console.error(`😕 We couldn't find "${srcArg}". Please check that the path exists.`);
        break;
      case 'EACCES':
      case 'EPERM':
        console.error(`😕 Permission denied. You may not have access to "${srcArg}" or "${destArg}".`);
        break;
      case 'ENOSPC':
        console.error(`😕 Not enough space on the disk to finish the copy.`);
        break;
      case 'EEXIST':
        console.error(`😕 Something already exists at "${destArg}" and we couldn't overwrite it.`);
        break;
      case 'EXDEV':
        console.error(`😕 Can't copy across different filesystems here. Try using "cp -r" instead.`);
        break;
      default:
        console.error(`😕 Something went wrong while copying the directory: ${err.message}`);
    }
    process.exitCode = 1;
  }
}

main();
```

