## `copy-dir.js`

```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const fsp = fs.promises;
const path = require('node:path');

const USAGE = `
Usage: node copy-dir.js <source-folder> <destination-folder>

Copies a folder and everything inside it (subfolders, files, symlinks).

Examples:
  node copy-dir.js ./photos ./backup
  node copy-dir.js /var/data /mnt/usb/data
`;

/** Errors we raised ourselves — the message is already friendly. */
class UserError extends Error {}

/** Turn a low-level OS error into something a human can act on. */
function explain(err) {
  switch (err && err.code) {
    case 'ENOENT':
      return 'The source folder could not be found. Check the path and try again.';
    case 'EACCES':
    case 'EPERM':
      return 'Permission denied. Check the folder permissions, or run with elevated privileges.';
    case 'ENOSPC':
      return 'There is not enough space left on the destination drive to finish the copy.';
    case 'EEXIST':
      return 'Something already exists at the destination. Remove it or pick another name.';
    case 'EBUSY':
      return 'The destination is being used by another program. Close it and try again.';
    case 'EXDEV':
      return 'The source and destination are on different devices that cannot be linked.';
    default:
      return err && err.message ? err.message : 'An unknown error occurred.';
  }
}

/**
 * Recursively copy `src` into `dest`.
 * If `dest` already exists as a folder, its contents are merged into it.
 */
async function copyTree(src, dest, stats) {
  await fsp.mkdir(dest, { recursive: true });

  const entries = await fsp.readdir(src, { withFileTypes: true });

  for (const entry of entries) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);

    try {
      if (entry.isDirectory()) {
        stats.dirs += 1;
        await copyTree(from, to, stats);
      } else if (entry.isSymbolicLink()) {
        const target = await fsp.readlink(from);
        await fsp.rm(to, { force: true }); // replace an existing link, don't follow it
        await fsp.symlink(target, to);
        stats.links += 1;
      } else if (entry.isFile()) {
        await fsp.copyFile(from, to); // preserves file permissions
        stats.files += 1;
      } else {
        stats.skipped += 1;
        console.warn(`  ⚠️  Skipped (not a normal file): ${from}`);
      }
    } catch (err) {
      // Add context without losing the original error code.
      err.message = `Failed on "${from}": ${err.message}`;
      throw err;
    }
  }
}

async function main() {
  const args = process.argv.slice(2);

  if (args.includes('-h') || args.includes('--help')) {
    console.log(USAGE);
    return;
  }

  const [srcArg, destArg] = args;
  if (!srcArg || !destArg) {
    console.error(USAGE);
    process.exitCode = 1;
    return;
  }

  const src = path.resolve(srcArg);
  const dest = path.resolve(destArg);

  // --- Sanity checks -------------------------------------------------------
  let srcStat;
  try {
    srcStat = await fsp.stat(src);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new UserError(`The source folder "${srcArg}" doesn't exist.`);
    }
    throw err;
  }

  if (!srcStat.isDirectory()) {
    throw new UserError(`"${srcArg}" is a file, not a folder.`);
  }

  if (src === dest) {
    throw new UserError('The source and destination are the same folder.');
  }

  const relative = path.relative(src, dest);
  if (relative && !relative.startsWith('..') && !path.isAbsolute(relative)) {
    throw new UserError(
      'The destination folder is inside the source folder — that would copy forever. Please pick a different destination.'
    );
  }

  try {
    const destStat = await fsp.stat(dest);
    if (!destStat.isDirectory()) {
      throw new UserError(`"${destArg}" already exists and is not a folder.`);
    }
  } catch (err) {
    if (err.code !== 'ENOENT') throw err; // a real error (e.g. permission)
    // Destination doesn't exist yet — that's fine, we'll create it.
  }

  // --- Do the copy ---------------------------------------------------------
  console.log(`📂 Copying "${src}"\n   ➜  "${dest}"`);
  const stats = { files: 0, dirs: 0, links: 0, skipped: 0 };
  const started = Date.now();

  await copyTree(src, dest, stats);

  const seconds = ((Date.now() - started) / 1000).toFixed(1);
  console.log(
    `\n✅ Done in ${seconds}s — ${stats.files} file(s), ${stats.dirs} folder(s), ${stats.links} link(s).`
  );
}

main().catch((err) => {
  if (err instanceof UserError) {
    console.error(`\n❌ ${err.message}\n`);
  } else {
    console.error(`\n❌ Copy failed: ${explain(err)}\n`);
  }
  process.exitCode = 1;
});
```

