```

## What it handles

| Situation | Result |
|---|---|
| Source folder missing | *"The source folder "./photos" doesn't exist."* |
| Source is a file | *""photos" is a file, not a folder."* |
| Destination inside source | Explains it would copy forever |
| Destination exists as a folder | Contents are merged into it |
| Permission denied / disk full / drive busy | Plain-language explanation of the OS error |
| Symlinks | Recreated as links (not followed) |
| Odd files (sockets, FIFOs) | Skipped with a warning instead of crashing |

Exit code is `0` on success and `1` on any failure, so it works in shell scripts and CI.

```js
#!/usr/bin/env node
/**
 * copy-dir.js — recursively copy a directory.
 *
 * Usage: node copy-dir.js <source> <destination>
 */

const fs = require('node:fs/promises');
const path = require('node:path');

async function copyDir(source, destination) {
  const src = path.resolve(source);
  const dest = path.resolve(destination);

  // Guard against copying a directory into itself / its own subdirectory,
  // which Node would otherwise handle unpredictably.
  if (dest === src || dest.startsWith(src + path.sep)) {
    throw new Error('The destination cannot be the source directory or a subdirectory of it.');
  }

  await fs.cp(src, dest, {
    recursive: true,
    force: true,       // overwrite existing files
    errorOnExist: false,
    preserveTimestamps: true,
  });
}

async function main() {
  const [source, destination] = process.argv.slice(2);

  if (!source || !destination) {
    console.log('Usage: node copy-dir.js <source> <destination>');
    process.exitCode = 1;
    return;
  }

  try {
    await copyDir(source, destination);
    console.log(`✅ Copied "${source}" to "${destination}" successfully!`);
  } catch (err) {
    console.log(`😕 Oops, something went wrong while copying the directory.`);
    console.log(`   Reason: ${err.message}`);
    process.exitCode = 1;
  }
}

main();
