A self-contained script that copies a directory recursively and turns any failure into a readable message instead of a stack trace.

```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');

const USAGE = `
Usage: node copy-dir.js <source-directory> <destination-directory>

Example:
  node copy-dir.js ./photos ./photos-backup
`.trim();

/**
 * Copy a directory recursively.
 * Uses fs.cp (Node 16.7+) and falls back to a manual copy on older versions.
 */
async function copyDir(src, dest) {
  if (typeof fs.cp === 'function') {
    await fs.cp(src, dest, { recursive: true, force: true });
    return;
  }

  // Fallback implementation for Node < 16.7
  const entries = await fs.readdir(src, { withFileTypes: true });
  await fs.mkdir(dest, { recursive: true });

  for (const entry of entries) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);

    if (entry.isDirectory()) {
      await copyDir(from, to);
    } else if (entry.isSymbolicLink()) {
      const target = await fs.readlink(from);
      await fs.symlink(target, to);
    } else {
      await fs.copyFile(from, to);
    }
  }
}

/** Turn a low-level filesystem error into something a human can act on. */
function friendlyError(error, src, dest) {
  switch (error.code) {
    case 'ENOENT':
      return `Could not find "${src}". Does it exist?`;
    case 'ENOTDIR':
      return `"${src}" is not a directory.`;
    case 'EACCES':
    case 'EPERM':
      return `Permission denied while copying "${src}" to "${dest}". Check the file permissions and try again.`;
    case 'EEXIST':
      return `"${dest}" already exists. Choose a different destination or remove it first.`;
    case 'ENOSPC':
      return `There is not enough space on the disk to finish copying into "${dest}".`;
    case 'EXDEV':
      return `Cannot copy across filesystems. Try copying to a location on the same disk.`;
    case 'ERR_FS_CP_EINVAL':
      return `The copy was interrupted or the destination is invalid.`;
    default:
      return `Something went wrong while copying "${src}" to "${dest}": ${error.message}`;
  }
}

async function main() {
  const args = process.argv.slice(2);

  if (args.includes('-h') || args.includes('--help')) {
    console.log(USAGE);
    return;
  }

  const [src, dest] = args;
  if (!src || !dest) {
    console.error('Missing arguments.\n');
    console.error(USAGE);
    process.exitCode = 1;
    return;
  }

  const srcPath = path.resolve(src);
  const destPath = path.resolve(dest);

  // 1. Does the source exist and is it a directory?
  let stats;
  try {
    stats = await fs.stat(srcPath);
  } catch (error) {
    console.error(`❌ ${friendlyError(error, srcPath, destPath)}`);
    process.exitCode = 1;
    return;
  }

  if (!stats.isDirectory()) {
    console.error(`❌ "${srcPath}" is not a directory — this script only copies directories.`);
    process.exitCode = 1;
    return;
  }

  // 2. Guard against copying a folder into itself (infinite recursion).
  if (destPath === srcPath || destPath.startsWith(srcPath + path.sep)) {
    console.error('❌ The destination cannot be the source folder or a folder inside it.');
    process.exitCode = 1;
    return;
  }

  // 3. Do the copy.
  try {
    await copyDir(srcPath, destPath);
    console.log(`✅ Copied "${srcPath}" to "${destPath}".`);
  } catch (error) {
    console.error(`❌ ${friendlyError(error, srcPath, destPath)}`);
    process.exitCode = 1;
  }
}

main().catch((error) => {
  console.error(`❌ Unexpected error: ${error.message}`);
  process.exitCode = 1;
});
